    (13, N'Arc of Lane County', N'In addition to advocating to protect the civil rights of people who experience disabilities, The Arc also provides supports and services to help people live, work and play in the community.', N'https://arclane.org/', N'info@arclane.org', N'Monday to Friday, 9 a.m. to 5 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'AdamW', '2024-09-21T21:06:11.677309'),
    (14, N'Aunt Bertha (Aka findhelp.org)', N'Also known as Find Help, Aunt Bertha is a national, searchable online database that connects people with services in their communities for a range of issues. In Eugene information is available about food pantries, cash assistance programs, and housing assistance programs.', N'https://www.auntbertha.com/find-social-services/oregon', N'', N'Accessible online, all the time', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-06T02:24:19.155638'),
    (15, N'Basic Rights Oregon', N'Works to advocate politically for the LGBTQ2SIA+ community. Affirms trans youth deserve to play sports, denounces dangerous attacks on kids. Call or check website for resources or referrals.', N'http://www.basicrights.org/', N'info@basicrights.org', N'Monday to Friday, 9 a.m. to 5 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'AdamW', '2024-09-21T21:17:06.426612'),
    (16, N'Bethel Branch Library', N'Wi-Fi and computer access available. Mobile hotspots available for borrow. Patrons can borrow from other library locations. ', N'https://www.eugene-or.gov/130/Eugene-Public-Library', N'libraryaskus@ci.eugene.or.us', N'Monday, Wednesday, Thursday, Friday, Saturday from 10 a.m. to 6 p.m.; Tuesday noon to 8 p.m.; closed Sunday', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'AdamW', '2024-09-21T21:20:59.303780'),
    (17, N'Bethesda Lutheran Church', N'Food pantry. Open the second and fourth Saturday of the month from 9:30 a.m. to noon, first come, first served. Emergency food bags (with two days of food provided) available Monday. Also provide some hygiene products. Thursday, 9am to 1pm.', N'https://bethesdalutheranchurch.com/', N'office@bethesdalutheranchurch.com', N'Monday through Thursday, 9am to 1pm day of every month, the second and fourth Saturday of every month,9:30 a.m. to noon', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'AdamW', '2024-09-21T21:51:00.041495'),
    (18, N'Better Living Center', N'A wide selection of free clothing and small household goods are available to anyone. No qualifying required.', N'https://florenceor.adventistchurch.org/ministries/lois-davidson-better-living-center', N'', N'Wednesday, Sunday 11 a.m. to 3 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-06T17:36:09.051262'),
    (19, N'Boys & Girls Clubs of Emerald Valley', N'After-school programs and activities for youth from 1st through 12th grade. Activities include academic support, art, athletics, and board games. Meal provided for children in the program. ', N'https://www.bgcev.org', N'Eugene Clubhouse:  members@bgcev.org    Bethel Clubhouse: bethel@bgcev.org', N'Hours vary seasonally, please check website for hours. Monday to Friday, 8:00 a.m. to 5:30 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-06T17:42:31.634476'),
    (20, N'Boys and Girls Aid', N'Services support children, youth and young adults in finding permanency via adoption and foster care. Information about shelter and housing, and all options pregnancy counseling. You can also text “Askme” to 503.841.2672  Chat or text only. Live chat on website available evenings and weekends.', N'https://www.boysandgirlsaid.org/options', N'info@boysandgirlsaid.org', N'Monday to Friday, 8:30 a.m. to 5 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'AdamW', '2024-09-21T22:06:31.135698'),
    (22, N'Buckley''s Sobering Services (through Willamette Family, Inc.)', N'The first step toward becoming sober. Sobering and medical detox on site. Walk up to the building, call, or get transportation from CAHOOTS. Spanish speakers available.', N'https://wfts.org/sobering.htm', N'', N'5pm to 5am every day', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-06T22:37:16.416775'),
    (23, N'Burrito Brigade', N'Vegetarian burritos are distributed Saturdays and Sundays 1:45 to 3 p.m. at various locations including Occupy Medical (1717 Centennial Blvd. Suites 4 & 7 in Springfield, Oregon) and in front of the White Bird Front Rooms (341 E 12th Ave, Eugene).', N'https://www.facebook.com/EugeneBurritoBrigade/', N'info@burritobrigade.org', N'Visit their Facebook page, events for current hours', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'AdamW', '2024-09-21T22:12:58.660622'),
    (24, N'Bushnell University - Counseling Center', N'Counselors are supervised Masters students in the Community Counseling program at Bushnell. Serving adults, couples, and children 12 and up. In-person or telehealth sessions. Fee for sessions is on a sliding scale, $10-up. Sessions free to Bushnell, UO and Lane Students. Currently there is a waitlist for appointments. ', N'https://www.bushnell.edu/life-at-bushnell/wellness-safety/counseling-center/', N'Individual counselors have email addresses. ', N'M-F, 8 a.m. to 8 p.m. Last call for appts. is at 7pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-06T22:45:42.450052'),
    (26, N'Café 60 - I.O.O.F. Hall', N'Individuals who are 60 years of age and over, and their spouses regardless of age, can enjoy a meal. Voluntary donations are welcome but not required. Reservations, however, are required. Please stop in or call to register. ', N'https://laneseniormeals.org/177/Caf-60-Locations', N'', N'Wednesday at 11:30 ', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'AdamW', '2024-09-21T22:31:16.536473'),
