    (40, N'Carry it Forward', N'Carry It Forward is a 501(c)3 that serves unhoused people in Lane County, Oregon, with a primary concentration in Eugene, Springfield, and rural areas in East Lane County.', N'https://www.carryitforward.net/', N'reception@carryitforward.net', N'Call for this information', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-08T00:45:37.464970'),
    (41, N'Catholic Community Services of Lane County - Eugene Service Center', N'Food and clothing pantries, SNAP enrollment assistance, assistance obtaining ID and birth certificates, rental and utility assistance, cold weather shelter assistance, bus passes, hygiene items, prescription and eyeglass vouchers.  Food delivery boxes for age 60+ may be available. ', N'https://www.ccslc.org/', N'', N'Clothing closet open Monday to Friday, 9 am to 12 pm. Food pantry open Monday, Wednesday, Friday, 8 am to 12 pm. Main hours for other services Monday, Tuesday, Wednesday, 8 am to 4 pm, Thursday 9 am to 4 pm.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-08T03:09:09.594604'),
    (42, N'Catholic Community Services of Lane County - Springfield Service Center', N'Food and clothing pantries, SNAP enrollment assistance, assistance obtaining ID and birth certificates, rental and utility assistance, cold weather shelter assistance, bus passes, hygiene items, prescription and eyeglass vouchers.  Food delivery boxes for age 60+ may be available.', N'https://www.ccslc.org/', N'help@ccslc.org', N'Clothing closet: Monday-Friday 9am-noon; Food pantry Monday, Wednesday, Friday 8am-noon; Main hours for other services: Monday, Tuesday, Wednesday, and Friday 8am-4pm, Thursday 9am-4pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'Lynnb', '2024-09-21T21:17:59.310970'),
    (43, N'Catholic Community Services Springfield Center', N'Provides one-on-one support and various rental assistance programs as funding is available. Call 541-345-3628 (extension 408) on Monday mornings at 9 a.m. to check the status of the rental assistance waiting list. Utility assistance is available at the above number. Please call or walk in to get more information. A food pantry, clothing closet, hygiene items, prescription assistance, housing referrals, utility help and more are also available.', N'https://www.ccslc.org/rentassistance', N'', N'Monday to Friday, 8 a.m. to 3 p.m.', 1, N'{"Name": {"Value": {"en": "Catholic Community Services Springfield Center"}}, "Description": {"Value": {"en": "Provides one-on-one support and various rental assistance programs as funding is available. Call 541-345-3628 (extension 408) on Monday mornings at 9 a.m. to check the status of the rental assistance waiting list. Utility assistance is available at the above number. Please call or walk in to get more information. A food pantry, clothing closet, hygiene items, prescription assistance, housing referrals, utility help and more are also available.", "es": "Ofrece apoyo personalizado y varios programas de asistencia para el alquiler según haya fondos disponibles. Llame al 541-345-3628 (extensión 408) los lunes por la mañana a las 9 a.m. para verificar el estado de la lista de espera de asistencia para el alquiler. La asistencia con los servicios públicos está disponible en el número anterior. Llame o visite para obtener más información. También se encuentran disponibles una despensa de alimentos, un armario de ropa, artículos de higiene, asistencia con recetas, referencias de vivienda, ayuda con servicios públicos y más."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 3 p.m.", "es": "Lunes a viernes de 8 a.m. a 3 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (45, N'Celebrate Recovery - Crossfire Outreach International', N'Celebrate Recovery is a safe place to find community and freedom from the issues that are controlling our lives.  Faith-based 12-step recovery support.', N'https://www.celebraterecovery.com', N'springfieldadventistchurchcr@gmail.com', N'Every Monday: Dinner is at 6 pm, followed by a large group meeting at 7 pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-09T23:48:37.204944'),
    (46, N'Celebrate Recovery - Dayspring Fellowship', N'Celebrate Recovery is a safe place to find community and freedom from the issues that are controlling our lives. Faith-based 12-step recovery support', N'https://www.celebraterecovery.com', N'', N'Thursday 6:15 p.m.', 0, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-09T23:53:33.462817'),
    (48, N'Celebrate Recovery - City First Church', N'Celebrate Recovery is a safe place to find community and freedom from the issues that are controlling our lives.  Faith-based 12-step recovery support', N'https://www.celebraterecovery.com', N'ryanmatsencr@gmail.com', N'Tuesday: Dinner is at 5pm; large group meeting at 6pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'Lynnb', '2024-09-21T22:01:30.464996'),
    (49, N'Celebrate Recovery - Calvary Chapel ', N'Celebrate Recovery is a safe place to find community and freedom from the issues that are controlling our lives.  Faith-based 12-step recovery support', N'https://www.celebraterecovery.com', N'cgcalvary@msn.com', N'Thursday: Dinner 6:15pm; main meeting 7pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-11T03:22:08.659394'),
    (50, N'Center for Community Counseling', N'Mental health services for low income adults. Classes and group sessions on managing emotions and parenting and long-term counseling. Sliding scale. No Oregon Health Plan.  Couples counseling, grandparents group; men''s group.', N'https://www.ccceugene.org/', N'', N'Monday to Thursday, 9 a.m. to 3 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'Lynnb', '2024-09-21T22:06:41.528512'),
    (51, N'Center for Family Development - North Building', N'Outpatient mental health programs for children, adolescents, and adults. Specializations include: child abuse, sexual behavior, depression, ADHD, anxiety, delinquent behavior, and group therapy. OHP accepted.  In-person or telehealth Zoom appointments available.', N'http://c-f-d.org/', N'', N'Monday to Friday, 8 a.m. to 5:30 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'Lynnb', '2024-09-21T22:07:55.547945'),
    (52, N'Center for Family Development Outpatient Substance Use Recovery', N'Services provided include: individual and group therapy, family therapy, peer support, urine analysis, and collaboration with referring agencies. In-person or telehealth zoom appointments available.', N'http://www.c-f-d.org/', N'', N'Monday to Friday, 8 a.m. to 5:30 p.m.', 1, N'{"Name": {"Value": {"en": "Center for Family Development Outpatient Substance Use Recovery"}}, "Description": {"Value": {"en": "Services provided include: individual and group therapy, family therapy, peer support, urine analysis, and collaboration with referring agencies. Please call to sign in.\\n\\nCOVID Update: All therapy is over Zoom or phone. All details subject to change during pandemic.", "es": "Los servicios ofrecidos en el Center for Family Development incluyen: terapia individual y grupal, terapia familiar, apoyo de pares, análisis de orina y colaboración con agencias de referencia. Llame para registrarse.\\n\\nActualización de COVID: toda la terapia se realiza a través de Zoom o por teléfono. Todos los detalles están sujetos a cambios durante la pandemia."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 5:30 p.m.", "es": "Lunes a viernes de 8 a.m. a 5:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-11T03:40:03.193416'),
    (53, N'Plaza de Nuestra Comunidad - Eugene Main Office', N'Provides for the local Latino population: social services, alcohol and addiction treatment, community health care, translation services for youth and adults.', N'https://plazacomunidad.org/', N'', N'Monday-Friday 9am - 6 pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-11T20:07:42.883268'),
