    (62, N'Community Health Clinics of Lane County - Springfield, 10th St', N'Health care center for all; accepts Oregon Health Plan. Accepting new patients. Lane County Family Planning services are available. Assistance with OHP applications is available.\\n\\nCOVID Update: Phone visits are available. Masks are required and all visitors and staff are screened on entry.', N'lanecounty.org/chc', N'', N'Monday to Friday, 8 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "Community Health Clinics of Lane County - Springfield, 10th St"}}, "Description": {"Value": {"en": "Health care center for all; accepts Oregon Health Plan. Accepting new patients. Lane County Family Planning services are available. Assistance with OHP applications is available.\\n\\nCOVID Update: Phone visits are available. Masks are required and all visitors and staff are screened on entry.", "es": "Centro de salud para todos, acepta Oregon Health Plan. Aceptando pacientes nuevos. Los servicios de planificación familiar del condado de Lane están disponibles. Hay ayuda disponible con las solicitudes del OHP.\\n\\nActualización de COVID: las visitas telefónicas están disponibles. Se requieren máscaras y todos los visitantes y el personal son examinados a la entrada."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 5 p.m.", "es": "Lunes a viernes de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (63, N'Community Health Centers of Lane County - Springfield, Olympic St', N'Lane County Family Planning services are available. Health care center for families; accepts Oregon Health Plan. Accepting new patients. Assistance with OHP applications is available.  Accepts some private insurance; call your insurance company to verify.  (This clinic is only a pediatric clinic.)', N'lanecounty.org/chc', N'', N'Monday to Friday, 8 a.m. to 5 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'Lynnb', '2024-09-21T22:37:00.010684'),
    (64, N'Community Kitchen at the Trinity Lutheran Church', N'To-go meals served.', N'http://tlccg.com/', N'tlc@tlccg.com', N'Tuesday/Thursday 5:15pm-6pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'Lynnb', '2024-09-21T22:37:37.924043'),
    (65, N'Community Outreach through Radical Empowerment (CORE)', N'CORE serves youth/young adults ages 16-29. Supply drops happen Tuesday, 4-7 pm. Reach out between 11-3 pm on Tuesdays if you need outreach supplies.', N'https://coreeugene.org/', N'Info@coreeugene.org', N'Varies, call or email for more information', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-13T22:08:09.299809'),
    (66, N'Community Reintegration Service Center', N'Eugene Vet Center. Reintegration and bereavement support of combat vets and survivors of military sexual trauma. Thursdays: Veteran Employment Specialist, WorkSource Lane, (8:30 a.m. - 3:30 p.m.) The Eugene Vet Center offers the following groups, please call the Eugene Vet Center for details:  PTSD, Vietnam Specific, OEF/OIF, Anger Management, Self-Esteem/Depression, Life Skills Building, DBT Emotional Skills, and Women''s MST Survivors Group.', N'https://www.lanecc.edu/esfs/va-education-benefits-certification-local-and-regional-veterans-service-agencies', N'', N'Monday to Friday, 8 a.m. to 4 p.m.', 1, N'{"Name": {"Value": {"en": "Community Reintegration Service Center"}}, "Description": {"Value": {"en": "Eugene Vet Center. Reintegration and bereavement support of combat vets and survivors of military sexual trauma. \\n\\nThursdays: Veteran Employment Specialist, WorkSource Lane, (8:30 a.m. - 3:30 p.m.)\\n\\nA counselor is available at the following locations once or twice a month, call the Eugene Vet Center for dates and times: Lane Community College, University of Oregon, Umpqua Community College, and Oregon State University.\\n\\nThe Eugene Vet Center offers the following groups, please call the Eugene Vet Center for details: PTSD, Vietnam Specific, OEF/OIF, Anger Management, Self-Esteem/Depression, Life Skills Building, DBT Emotional Skills, and Women''s MST Survivors Group.", "es": "Centro de Veteranos de Eugene. Apoyo para la reintegración y el duelo de los veteranos de combate y sobrevivientes de trauma sexual militar.\\n\\nJueves: Especialista en empleo de veteranos, WorkSource Lane, (8:30 a.m. - 3:30 p.m.)\\n\\nHay un consejero disponible en los siguientes lugares una o dos veces al mes, llame al Centro de Veteranos de Eugene para conocer las fechas y horarios: Lane Community College, University of Oregon, Umpqua Community College y Oregon State University.\\n\\nEl Eugene Vet Center ofrece los siguientes grupos, por favor llame al Eugene Vet Center para más detalles: PTSD, Vietnam Specific, OEF / OIF, Anger Management, Autoestima / Depression, Life Skills Building, DBT Emotional Skills y Women''s MST Survivors Group."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 5 p.m.", "es": "Lunes a viernes de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-14T02:27:09.845987'),
    (67, N'Community Sharing Program', N'Food boxes, rent, utility and water assistance, prescription assistance. Help getting an ID. Laundry, shower, propane and gas vouchers. Bus passes for medical appointments and job interviews. More services available. ', N'https://communitysharing.org/', N'info@communitysharing.org', N'Monday 1:30pm-6pm, Tuesday-Friday 11am-3:30pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-19T00:15:45.947146'),
    (68, N'Community Supported Shelters', N'Provides transitional shelter in Conestoga hut. People interested in obtaining shelter within a Safe Spot Community are able to sign up at CSS''s main office located at 1160 Grant St in Eugene. Walk-in hours are Tuesday - Friday, 1-4 pm. Program includes plan advisors and peer support. Wheelchair accessible.', N'https://communitysupportedshelters.org/', N'office@cssoregon.org', N'Tuesday - Friday, 1 - 4 pm', 1, N'{"Name": {"Value": {"en": "Community Supported Shelters"}}, "Description": {"Value": {"en": "Provides transitional shelter in Conestoga hut. Safe Spot Community, along with plan advisers and peer support. Apply at office. Wheelchair accessible.", "es": "Ofrece refugio transitorio en la cabaña de Conestoga. Safe Spot Community, junto con asesores del plan y apoyo de pares. Aplicar en la oficina. Silla de ruedas accesible."}}, "HoursOfOperation": {"Value": {"en": "Wednesday, Thursday, Friday 1 p.m. to 4 p.m.", "es": "Miércoles, jueves, viernes 1 p.m. a las 4 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-19T00:26:40.669742'),
    (69, N'Community Veterinary Center', N'Sliding-scale clinic, by appointment only. Basic care includes: wellness checks, vaccines, blood work, euthanasia, dental treatments, prescriptions, diagnosis and treatments, radiology, sterile surgery.', N'http://www.communityvet.org/', N'', N'Tuesday - Friday 9am - 4pm', 1, N'{"Name": {"Value": {"en": "Community Veterinary Center"}}, "Description": {"Value": {"en": "Sliding-scale clinic, by appointment only. Basic care includes: wellness checks, vaccines, blood work, euthanasia, dental treatments, prescriptions, diagnosis and treatments, radiology, sterile surgery, and spay/neuter.\\n\\nCOVID Update: Masks required.", "es": "Clínica de escala móvil, solo con cita previa. La atención básica incluye: controles de bienestar, vacunas, análisis de sangre, eutanasia, tratamientos dentales, recetas, diagnóstico y tratamientos, radiología, cirugía estéril y esterilización / castración.\\n\\nActualización de COVID: se requieren máscaras."}}, "HoursOfOperation": {"Value": {"en": "Tuesday, Wednesday, Thursday from 9 a.m. to 4 p.m.", "es": "Martes, miércoles, jueves de 9 a.m. a 4 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-19T00:30:46.703620'),
    (70, N'Coordinated Entry', N'Connects houseless individuals with services like emergency shelter, mortgage and foreclosure assistance, and rental assistance.', N'https://www.lanecounty.org/cms/one.aspx?pageId=12711062', N'', N'Call for service', 1, N'{"Name": {"Value": {"en": "Coordinated Entry"}}, "Description": {"Value": {"en": "Connects houseless individuals with services that will rapidly end their houselessness. \\n\\nCOVID Update: No drop in. Call to make an appointment.", "es": "Conecta a las personas sin hogar con servicios que rápidamente terminarán con su falta de hogar.\\n\\nActualización de COVID: No se puede visitar. Llame para hacer una cita."}}, "HoursOfOperation": {"Value": {"en": "Call for service", "es": "Llame al servicio"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-19T00:47:14.064339'),
    (71, N'Cornerstone Community Housing', N'Affordable housing and resident services programming.', N'https://cornerstonecommunityhousing.org/housing-communities/', N'info@cornerstonecommunityhousing.org', N'Monday - Thursday, 10am -- 4pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-19T00:51:41.085384'),
    (72, N'Cottage Grove Public Library', N'Computers and WIFI available.', N'https://www.cottagegrove.org/library', N'holds@cottagegrove.org', N'Mon & Tues 11am - 7pm | Wed, Thurs, Fri 10am - 6pm | Sat 10am - 4pm | Closed Sunday', 1, N'{"Name": {"Value": {"en": "Cottage Grove Public Library"}}, "Description": {"Value": {"en": "COVID Update: Building is closed, including browsing and computers. Curbside pickup Monday to Friday. Call ahead of time to arrange a pick up of items.", "es": "Actualización de COVID: el edificio está cerrado, incluida la navegación y las computadoras. Recogida en la acera de lunes a viernes. Llame con anticipación para organizar la recogida de artículos."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 3 to 5 p.m.", "es": "Lunes a viernes de 15 a 17 horas"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-19T00:57:16.193640'),
    (73, N'Creswell Food Pantry', N'Once a month food box—plus, four extra times during the year. Bring a box. 3-5 days of food, 20 lbs per person. Provide a piece of mail to confirm address. Help for those with no address.', N'communityfoodforcreswell.org', N'susanblachnik@gmail.com', N'Thursday 9am-noon; closed on major holidays', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-19T01:09:37.831264'),
    (74, N'Creswell Library', N'Internet access and library services.', N'https://www.creswell-library.org/', N'service.desk@creswell-library.org', N'Mon 12 - 6pm | Tues, Wed, Thurs 10am - 7pm | Fri 12 - 6pm | Sat 10am - 4pm | Closed Sunday', 1, N'{"Name": {"Value": {"en": "Creswell Public Library"}}, "Description": {"Value": {"en": "Wi-Fi available in the parking lot.", "es": "Wi-Fi disponible en el estacionamiento."}}, "HoursOfOperation": {"Value": {"en": "Building currently closed", "es": "Edificio actualmente cerrado"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-19T01:17:27.404011'),
    (75, N'Cross Fire Ministries (Hands of Hope)', N'Food boxes available from 12 - 4pm every Thursday (except for the first Thursday of the month). Breakfast on Sunday from 8:30 - 10:30am (not take-out).', N'https://www.mycrossfire.com/cgi-bin/htmlos.cgi/apps/ministries/ministries.html?mid=food_ministry&ld=cfom', N'info@mycrossfire.com', N'12 - 4pm every Thursday (except for the first Thursday of the month). Breakfast on Sunday from 8:30 - 10:30am (not take-out)', 1, N'{"Name": {"Value": {"en": "Cross Fire Hands of Hope"}}, "Description": {"Value": {"en": "Food boxes available on Thursdays noon to 4 p.m. Closed on the first Thursday of every month. \\n\\nTo-go meals available Thursdays at 6:15 p.m. and Sundays at 8:30 a.m.", "es": "Cajas de comida disponibles los jueves de 12 a 4 p.m. Cerrado el primer jueves de cada mes.\\n\\nComidas para llevar disponibles los jueves a las 6:15 p.m. y los domingos a las 8:30 a.m."}}, "HoursOfOperation": {"Value": {"en": "Thursday noon to 4 p.m. and to-go meals Thursdays 6:15 p.m., Sundays 8:30 a.m.", "es": "Jueves mediodía a 4 p.m. y comidas para llevar los jueves a las 6:15 p.m., los domingos a las 8:30 a.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-19T02:17:31.005593'),
    (77, N'Diamond Express Transportation Service', N'Ticket books available: $10 per ticket, $25 per book', N'https://www.ltd.org/system-map/route_900/', N'', N'Mon - Fri 6am - 7pm, Sat 7am - 7pm, Closed Sunday', 1, N'{"Name": {"Value": {"en": "Diamond Express Transportation Service"}}, "Description": {"Value": {"en": "COVID Update: Currently on hold due to pandemic.", "es": "Actualización de COVID: actualmente en espera debido a una pandemia."}}, "HoursOfOperation": {"Value": {"en": "Currently on hold", "es": "Actualmente en espera"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-19T02:28:58.820655'),
    (78, N'Early Assessment and Support Alliance (EASA)', N'The First Episode Program helps people ages 12-29 who have recently experienced their first psychotic break. Services provided include: assessment, counseling, peer support, vocational education, job search assistance, medication management and case management.', N'http://www.easacommunity.org/', N'', N'Monday - Thursday 8am - 7pm, Friday 8am - 5pm', 1, N'{"Name": {"Value": {"en": "Early Assessment and Support Alliance (EASA)"}}, "Description": {"Value": {"en": "The First Episode Program helps people ages 15-25 who have recently experienced their first psychotic break. Services provided include: assessment, counseling, peer support, vocational education, job search assistance, medication management and case management.", "es": "El Programa Primer Episodio (First Episode Program) ayuda a las personas de entre 15 y 25 años que han experimentado recientemente su primer brote psicótico. Los servicios incluyen: evaluación, consejería, apoyo de pares, educación vocacional, asistencia en la búsqueda de empleo, administración de medicamentos y administración de casos."}}, "HoursOfOperation": {"Value": {"en": "Monday, Tuesday, Thursday from 8:30 a.m. to 6 p.m.; Wednesday 9 a.m. to 6 p.m.; Friday 8 a.m. to 5 p.m.", "es": "Lunes, martes, jueves de 8:30 a.m. a 6 p.m.; Miércoles 9 a.m. a 6 p.m.; Viernes de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-19T02:33:36.932987'),
    (80, N'Egan Warming Centers', N'Provides warm places to sleep and warm meals when temperatures drop below 30 degrees between November and March. There are several host sites, please check website to see which sites are active.', N'http://www.eganwarmingcenter.com/about-us/', N'info@eganwarmingcenter.com', N'Cold winter nights', 1, N'{"Name": {"Value": {"en": "Egan Warming Centers"}}, "Description": {"Value": {"en": "Provides warm places to sleep when temperatures drop below 30 degrees between November 15th and March 31st. There are several host sites, including a site dedicated to homeless youth. Please check website to see which sites are active.", "es": "Ofrece lugares cálidos para dormir cuando las temperaturas caen por debajo de los 30 grados entre el 15 de noviembre y el 31 de marzo. Hay varios sitios de acogida, incluido un sitio dedicado a los jóvenes sin hogar. Consulte el sitio web para ver qué sitios están activos."}}, "HoursOfOperation": {"Value": {"en": "Cold winter nights", "es": "Noches frías de invierno"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-19T18:52:27.667014'),
    (81, N'EMERGENCE EUGENE', N'Provides substance abuse, gambling, addiction, and mental health treatment. Support groups, and outpatient care. Specializes in Dialectical Behavior Therapy. Oregon Health Plan accepted. Call for appointment, no walk-in.\\n\\nCOVID Update: Tele-health and Zoom available.', N'http://4emergence.com/', N'hr@4emergence.com', N'Monday to Friday, 8 a.m. to 5 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'DavidD', '2024-09-21T21:55:28.309603'),
    (82, N'Emergence Addiction and Behavioral Therapies - Juntos', N'Provides substance abuse, gambling, addiction, and mental health treatment. Support groups, and outpatient care. Call for appointment, no walk in. Spanish spoken.', N'http://www.4emergence.com/programs/juntos', N'rdelao@4emergence.com', N'Monday to Friday, 8 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "Emergence Addiction and Behavioral Therapies - Juntos"}}, "Description": {"Value": {"en": "Provides substance abuse, gambling, addiction, and mental health treatment. Support groups, and outpatient care. Specializes in Dialectical Behavior Therapy. Call for appointment, no walk in. Spanish spoken.", "es": "Ofrece tratamiento para juegos de azar, abuso de sustancias, adicciones y salud mental. Grupos de apoyo y atención ambulatoria. Se especializa en DBT (Terapia de Conducta Dialéctica). OHP aceptado. Llame para hacer una cita, no se puede entrar sin cita previa."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 5 p.m.", "es": "Lunes a viernes de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-19T21:29:22.621823'),
    (84, N'EPUD Helping Hands', N'Helps customers pay their EPUD bills. The maximum award is $600. First come, first serve, one grant per household a year.', N'https://www.epud.org/news/helping-hands-assistance-program-now-open/', N'', N'Monday to Thursday, 7:30 a.m. to 5:30 p.m.', 1, N'{"Name": {"Value": {"en": "EPUD Helping Hands"}}, "Description": {"Value": {"en": "Helps customers pay their EPUD bills. The maximum award is $300. First come, first serve, one grant per household a year.", "es": "Ayuda a los clientes a pagar sus facturas EPUD. El premio máximo es de $300. Primero en llegar, primero en servir, una subvención por hogar al año."}}, "HoursOfOperation": {"Value": {"en": "Monday to Thursday, 7:30 a.m. to 6 p.m.", "es": "Lunes a jueves de 7:30 a.m. a 6 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-19T22:02:10.308616'),
    (86, N'Eugene Faith Center', N'Food boxes available. The dates every month are updated on the website.', N'https://www.eugenefaithcenter.org/food-pantry', N'', N'Two Thursdays every month, 2 to 4 p.m.', 1, N'{"Name": {"Value": {"en": "Eugene Faith Center"}}, "Description": {"Value": {"en": "Food boxes available. The dates every month are updated on the website.", "es": "Cajas de comida disponibles. Las fechas de cada mes se actualizan en el sitio web."}}, "HoursOfOperation": {"Value": {"en": "Two Thursdays every month, 2 to 4 p.m.", "es": "Dos jueves al mes, de 2 a 4 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (87, N'Eugene Mission', N'The Mission offers a comprehensive range of services to help individuals transition off the streets. Guests checking into the Rescue Shelter are provided with up to 14 days of shelter, meals, shower facilities, and chaperoned convenience store trips. Check-in is at the Main office, 1542 W 1st Ave, 8am - 4pm. Service animals with current licenses and vaccination tags are welcome at the Mission. While no drug testing occurs upon entry to the shelter, there is a zero-tolerance policy for possession or use of drugs or alcohol on site. After 14 days of shelter, guests have the option to participate in one of the Mission''s Revitalization Programs; passing a drug test is required to participate in these programs. Both programs are free and provide goal setting, vocational training, life skills classes, and activities. The Life Change program is a 12 - 18 month residential relapse prevention program. The goal for members after graduation is to reenter society with employment or sustainable income and housing.', N'https://eugenemission.org/', N'info@eugenemission.org', N'Every day, 8am - 4pm', 1, N'{"Name": {"Value": {"en": "Eugene Mission"}}, "Description": {"Value": {"en": "Meals for guests only. \\n\\nFor overnight shelters, a lottery is held at 9 a.m. for available spaces, and all guests must sign in before 9 a.m. There is a men’s shelter, a women’s shelter, and a shelter for women with children (under 17 years of age). Overnight guests also have the following services available: laundry facilities, showers, meals, clothing, mail service, haircuts, case management, referrals.\\n\\nWalk-in day shelters are available. The men’s day shelter is available from 7 a.m. to 1 p.m., 4 to 6 p.m. Monday through Friday; the women’s day shelter is available from 7 a.m. to 1 p.m. Monday through Friday. Women and children are welcome most times of the day, Monday to Friday (please call the center for availability, if you can). Clothing is available to those who request items before 9 a.m., Monday to Friday. \\n\\nShowers are available for those who stay overnight and for those who walk in. Men can shower from 8 a.m. to 1 p.m. and 4:30 to 6:30 p.m. Monday to Friday. Women can shower from 9 to 11 a.m. Monday to Friday. Women with children can contact the Mission for shower time. \\n\\nFree haircuts are available, please call for the schedule. Clothing is available to those who request items before 9 a.m., Monday to Friday.", "es": "Comidas solo para invitados.\\n\\nPara los refugios para pasar la noche, se realiza un sorteo a las 9 a.m. para los espacios disponibles, y todos los huéspedes deben registrarse antes de las 9 a.m. Hay un refugio para hombres, un refugio para mujeres y un refugio para mujeres con niños (menores de 17 años). Los huéspedes que pasan la noche también tienen disponibles los siguientes servicios: lavandería, duchas, comidas, ropa, servicio de correo, cortes de cabello, manejo de casos, referencias.\\n\\nSe encuentran disponibles refugios de día sin cita previa. El refugio diurno para hombres está disponible de 7 a.m. a 1 p.m., de 4 a 6 p.m. De lunes a viernes; el refugio de día de la mujer está disponible de 7 a.m. a 1 p.m. De lunes a viernes. Las mujeres y los niños son bienvenidos la mayoría de las veces del día, de lunes a viernes (si puede, llame al centro para conocer la disponibilidad). La ropa está disponible para quienes soliciten artículos antes de las 9 a.m., de lunes a viernes.\\n\\nLas duchas están disponibles para quienes se quedan a pasar la noche y para quienes entran. Los hombres pueden ducharse de 8 a.m. a 1 p.m. y de 4:30 a 6:30 p.m. De lunes a viernes. Las mujeres pueden ducharse de 9 a 11 a.m. de lunes a viernes. Las mujeres con niños pueden comunicarse con la Misión para la hora de la ducha.\\n\\nHay cortes de pelo gratuitos disponibles, llame para conocer el horario. La ropa está disponible para quienes soliciten artículos antes de las 9 a.m., de lunes a viernes."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 7 a.m. to 1 p.m.", "es": "Lunes a viernes de 7 a.m. a 1 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-19T23:05:48.172042'),
    (88, N'Eugene Police Non-Emergency Line', N'Eugene Police non-emergency line', N'https://www.eugene-or.gov/4423/Police', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Eugene Police Non-Emergency Line"}}, "Description": {"Value": {"en": "Eugene Police non-emergency line", "es": "Línea de no emergencia de la policía de Eugene"}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (89, N'Eugene Public Library', N'Wi-Fi and computer access available; Wi-Fi mobile hot spots can be checked out. Spanish and American Sign Language spoken. Small conference rooms available for free.', N'https://www.eugene-or.gov/4422/Eugene-Public-Library', N'libraryaskus@ci.eugene.or.us', N'Monday to Thursday, 10 a.m. to 8 p.m.; Friday to Sunday, 10 a.m. to 6 p.m.', 1, N'{"Name": {"Value": {"en": "Eugene Public Library"}}, "Description": {"Value": {"en": "Wi-Fi and computer access available. Spanish and American Sign Language spoken.", "es": "Wi-Fi y acceso a computadora disponible. Se habla español y lenguaje de señas americano."}}, "HoursOfOperation": {"Value": {"en": "Monday to Thursday, 10 a.m. to 8 p.m.; Friday to Sunday, 10 a.m. to 6 p.m.", "es": "Lunes a jueves de 10 a.m. a 8 p.m.; viernes a domingo de 10 a.m. a 6 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-20T00:41:37.796664'),
    (90, N'Eugene Service Station Syringe Drop-off ', N'Syringe drop off in black box. Syringe exchange, Thursdays 1 - 3pm.', N'https://hivalliance.org/prevent/syringe-services/', N'prevention@allianceor.org', N'Drop off every day, all hours. Syringe exchange, Thursdays 1 - 3pm', 1, N'{"Name": {"Value": {"en": "Eugene Service Station Syringe Drop-off"}}, "Description": {"Value": {"en": "Syringe drop off", "es": "Caída de la jeringa"}}, "HoursOfOperation": {"Value": {"en": "Every day, 8 a.m. to 5 p.m.", "es": "Todos los días de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-20T00:46:55.775546'),
    (91, N'Eugene Seventh Day Adventist Church', N'Health, cooking, grief recovery, and financial planning classes. Contact church for schedule and for information about free meals.', N'https://eugeneor.adventistchurch.org/', N'', N'Contact church for hours', 1, N'{"Name": {"Value": {"en": "Eugene Seventh Day Adventist Church"}}, "Description": {"Value": {"en": "Free meals on the 2nd, 3rd and 4th Saturdays of each month, 1 p.m.", "es": "Comida gratis el segundo, tercer y cuarto sábado de cada mes, a la 1 p.m."}}, "HoursOfOperation": {"Value": {"en": "The second and fourth Saturday at 1 p.m.", "es": "El segundo y cuarto sábado a la 1 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-20T00:52:34.647568'),
    (92, N'Eugene Springfield Solidarity Network (ESSN)', N'ESSN brings together labor unions, student groups, religious congregations, and community organizations to support the civil and economic rights of all working people—especially the right to a decent standard of living, the right to a stable job, and the right to organize.', N'https://www.solidaritynetwork.org', N'', N'Monday to Friday, 9 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "Eugene Springfield Solidarity Network (ESSN)"}}, "Description": {"Value": {"en": "ESSN brings together labor unions, student groups, religious congregations, and community organizations to support the civil and economic rights of all working people—especially the right to a decent standard of living, the right to a stable job, and the right to organize.", "es": "ESSN reúne a sindicatos, grupos de estudiantes, congregaciones religiosas y organizaciones comunitarias para apoyar los derechos civiles y económicos de todos los trabajadores, especialmente el derecho a un nivel de vida digno, el derecho a un trabajo estable y el derecho a organizarse."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 9 a.m. to 5 p.m.", "es": "Lunes a viernes de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (93, N'Eugene VA Heathcare Center', N'Outpatient clinic; same-day-access clinic and pharmacy.', N'https://www.roseburg.va.gov/locations/eugene.asp', N'', N'Monday to Friday, 9am - 5pm', 1, N'{"Name": {"Value": {"en": "Eugene VA Heathcare Center"}}, "Description": {"Value": {"en": "Full service hospital for veterans.", "es": "Hospital de servicio completo para veteranos."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 4:30 p.m.", "es": "Lunes a viernes de 8 a.m. a 4:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-20T01:05:43.129704'),
    (94, N'Eugene Vet Center', N'Individual, family and group mental health counseling for vets and the families of vets who served in combat in need of readjustment to society or for those who are experiencing trauma.', N'https://www.va.gov/find-locations/facility/vc_0626V', N'', N'Monday to Saturday, 8 a.m. to 4:30 p.m.', 1, N'{"Name": {"Value": {"en": "Eugene Vet Center"}}, "Description": {"Value": {"en": "Individual, family and group mental health counseling for vets and the families of vets who served in combat in need of readjustment to society or for those who are experiencing trauma.\\n\\nCOVID Update: In person initial appointments and then scheduled on a case-by-case basis. Employment assistance is suspended through the end of the year and likely through June, 2021.", "es": "Asesoramiento de salud mental individual, familiar y grupal para los veterinarios y las familias de los veterinarios que sirvieron en combate en necesidad de reajuste a la sociedad o para aquellos que están experimentando un trauma.\\n\\nActualización de COVID: citas iniciales en persona y luego programadas caso por caso. La asistencia para el empleo está suspendida hasta fin de año y probablemente hasta junio de 2021."}}, "HoursOfOperation": {"Value": {"en": "Monday to Saturday, 8 a.m. to 4:30 p.m.", "es": "Lunes a viernes de 8 a.m. a 4:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-20T01:09:54.472751'),
    (95, N'EWEB Customer Care', N'Any customers struggling to pay their bills should call EWEB at 541-685-7000 M-F 8:30 a.m. - 5 p.m. First-come, first-serve. Application opens the first business day of each month. Customers may apply online.', N'http://www.eweb.org/residential-customers/income-based-assistance', N'', N' 8:30 AM to 5 PM', 1, N'{"Name": {"Value": {"en": "EWEB Customer Care"}}, "Description": {"Value": {"en": "Any customers struggling to pay their bills should call EWEB at 541-685-7000 M-F 9 a.m. - 6:30 p.m. First-come, first-serve. Application opens the first business day of each month.", "es": ""}}, "HoursOfOperation": {"Value": {"en": "9:00 AM to 6:30 PM", "es": "Monday through Friday"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-20T01:15:08.776378'),
    (96, N'Family Relief Nursery', N'Provides a therapeutic classroom for children six weeks to five years old; scheduled respite program for ages six weeks to six years, but call ahead for availability. Parent education and support; Latinx outreach. Information and referral services also provided. Spanish and English spoken.', N'http://www.frncg.org/', N'info@frncg.org', N'Monday-Friday 8am-4pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-20T01:19:50.355480'),
    (97, N'Fern Ridge Public Library', N'Wi-Fi is available on the grounds 24/7. Curbside pickup and phone reference is available. Call or use the catalog online to arrange for holds.', N'http://fernridgelibrary.org/', N'', N'Tuesday - Friday 10am - 7pm, Monday & Saturday 10am - 5pm', 1, N'{"Name": {"Value": {"en": "Fern Ridge Public Library"}}, "Description": {"Value": {"en": "Wi-Fi is available on the grounds 24/7. Curbside pickup and phone reference is available. Call or use the catalog online to arrange for holds.\\n\\nCovid Update: Building closed for pandemic.", "es": "La conexión Wi-Fi está disponible las 24 horas, los 7 días de la semana. Recogida en la acera y referencia telefónica disponible. Llame o utilice el catálogo en línea para concertar reservas.\\n\\nActualización de Covid: Edificio cerrado por pandemia."}}, "HoursOfOperation": {"Value": {"en": "Monday to Saturday, 10 a.m. to 4 p.m.", "es": "Lunes a sábado de 10 a.m. a 4 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-20T15:36:46.913628'),
    (98, N'Fern Ridge Service Center', N'A variety of activities and programs with low or no cost for individuals age 50 and over. Food boxes for all ages. Cafe 60 and Meals on Wheels Monday, Wednesday, Friday 10am - 12:30pm. Information and referrals, limited outreach casework. Limited financial assistance for energy bills, prescriptions, scholarships for youth activities.', N'https://midlanecares.com/', N'fernridgeservicecenter@gmail.com', N'Monday - Friday 9am - 2pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-20T15:46:32.987521'),
    (99, N'First Christian Church - Helping Hearts', N'Provides clothing for all ages, including baby clothes, kitchen items, and bedding to those in need. Items are used and in good condition.', N'https://www.heartofeugene.org/', N'', N'Tuesday and Thursday noon to 2 p.m.', 1, N'{"Name": {"Value": {"en": "First Christian Church - Helping Hand Room"}}, "Description": {"Value": {"en": "Provides clothing for all ages, including baby clothes, kitchen items, and bedding to those in need. Items are used and in good condition.", "es": "Ofrece ropa para todas las edades, incluida ropa de bebé, artículos de cocina y ropa de cama para los necesitados. Los artículos están usados y en buenas condiciones."}}, "HoursOfOperation": {"Value": {"en": "Tuesday and Thursday noon to 2 p.m.", "es": "Martes y jueves de mediodía a 2 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-20T15:51:45.241024'),
    (101, N'First Place Family Center', N'Offers a daytime facility for families with children, meals, mail service, laundry, computers, preschool, limited overnight accommodations, and referrals for jobs, housing and recovery. Waiting list for overnight accommodations. Spanish spoken.', N'https://www.svdp.us/what-we-do/homeless-services/first-place-family-center/', N'', N'Every day 9 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "First Place Family Center"}}, "Description": {"Value": {"en": "Offers a daytime facility for families with children, meals, mail service, laundry, computers, preschool, limited overnight accommodations, and referrals for jobs, housing and recovery. Waiting list for overnight accommodations. Spanish spoken.\\n\\nCOVID Update: Two separate blocks of time for the preschool. Only six non-staff people inside the building at a time. Meals are to go.", "es": "Ofrece instalaciones diurnas para familias con niños, comidas, servicio de correo, lavandería, computadoras, preescolar, alojamiento limitado durante la noche y referencias para trabajos, vivienda y recuperación. Lista de espera para alojamiento durante la noche. Se habla español.\\n\\nActualización de COVID: dos bloques de tiempo separados para el preescolar. Solo seis personas que no pertenecen al personal dentro del edificio a la vez. Las comidas son para llevar."}}, "HoursOfOperation": {"Value": {"en": "Every day 9 a.m. to 5 p.m.", "es": "Todos los días de 9 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-06-04T02:14:13.940293'),
    (102, N'FISH / Trinity United Methodist Church', N'Provides emergency food, propane and prescription medication assistance to individuals and families. Operates a food cupboard and takes calls for food, prescription medication and propane assistance, five days a week.', N'https://trinityumceugene.org/fish-food-pantry/', N'', N'Monday to Friday, 10:30 a.m. to 1:30 p.m.', 1, N'{"Name": {"Value": {"en": "FISH / Trinity United Methodist Church"}}, "Description": {"Value": {"en": "Provides emergency food, propane and prescription drug assistance to individuals and families. Operates a food cupboard and takes calls for food, prescription drug and propane assistance five days a week.\\n\\nPhone-in a request for food and pick up from 2 to 3 p.m. the same day. The building is closed. Food provided once a month. ID required.", "es": "Ofrece asistencia de emergencia con alimentos, propano y medicamentos recetados a individuos y familias. Opera un armario de alimentos y recibe llamadas de asistencia para alimentos, medicamentos recetados y propano cinco días a la semana.\\n\\nSolicite comida por teléfono y luego recoja la comida de 2 a 3 p.m. el mismo día. El edificio esta cerrado. Alimento ofrecidos una vez al mes. Se requiere identificación."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 10:30 a.m. to 1:30 p.m.", "es": "Lunes a viernes de 10:30 a.m. a 1:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-08-07T03:29:56.282986'),
    (103, N'Florence Food Share', N'Free food pantry.', N'http://www.florencefoodshare.org/', N'info@florencefoodshare.org', N'Monday to Friday, 9:30 a.m. to 1 p.m.; Monday and Wednesday, 4 to 6 p.m.; the second and fourth Saturday, 10 a.m. to 1 p.m.', 1, N'{"Name": {"Value": {"en": "Florence Food Share"}}, "Description": {"Value": {"en": "Free food pantry.", "es": "Despensa de comida gratis."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 9:30 a.m. to 1 p.m.; Monday and Wednesday, 4 to 6 p.m.; the second and fourth Saturday, 10 a.m. to 1 p.m.", "es": "Lunes a viernes de 9:30 a.m. a 1 p.m.; lunes y miércoles de 4 a 6 p.m.; el primer y tercer sábado de 10 a.m. a 1 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-08-07T03:33:22.784101'),
    (104, N'FOOD for Lane County', N'Call for a location to pick up food.', N'https://foodforlanecounty.org/', N'info@foodforlanecounty.org', N'Monday to Friday, 9 a.m. to 4 p.m.', 1, N'{"Name": {"Value": {"en": "FOOD for Lane County"}}, "Description": {"Value": {"en": "Call for a location to pick up food.\\n\\nCOVID Update: All programs still operating—call or access website for any changes that might be occurring at specific sites.", "es": "Llame para pedir un lugar para recoger alimentos.\\n\\nActualización de COVID: todos los programas siguen funcionando; llame o acceda al sitio web para conocer cualquier cambio que pueda estar ocurriendo en sitios específicos."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 9 a.m. to 4 p.m.", "es": "Lunes a viernes de 9 a.m. a 4 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-06-04T02:16:35.372563'),
    (105, N'FOOD For Lane County - The Dining Room', N'Serving to-go meals for first 250 guests. Must be 18 or older unless with legal guardian.', N'https://foodforlanecounty.org/get-help/fflcs-dining-room/', N'', N'Monday to Thursday, noon to 2:45 p.m.', 1, N'{"Name": {"Value": {"en": "FOOD For Lane County - The Dining Room"}}, "Description": {"Value": {"en": "Serving to-go meals for first 250 guests. Must be 18 or older unless with legal guardian.", "es": "Sirve comidas para llevar para los primeros 250 invitados. Debe tener 18 años o más a menos que esté con un tutor legal."}}, "HoursOfOperation": {"Value": {"en": "Monday to Thursday, noon to 2:45 p.m.", "es": "Lunes a jueves de mediodía a 2:45 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (106, N'Food Not Bombs', N'Nutritious, vegan meal served Fridays at 4 p.m. in the Park Blocks across from the courthouse.', N'https://www.facebook.com/foodnotbombseugene/', N'', N'Friday 4 p.m.', 1, N'{"Name": {"Value": {"en": "Food Not Bombs"}}, "Description": {"Value": {"en": "Nutritious, vegan meal served Fridays at 4 p.m. in the Park Blocks across from the courthouse.", "es": "Comida vegana nutritiva servida los viernes a las 4 p.m. en las cuadras del parque frente al palacio de justicia."}}, "HoursOfOperation": {"Value": {"en": "Friday 4 p.m.", "es": "Viernes a las 4 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (107, N'FreedomPop', N'Requires an email and place to list as your physical address, $5 GSM SIM kit to start Free monthly plan, $17 a month for Premium plan. One option is compatible with most unlocked GSM AT&T and T-Mobile phones, and another is compatible with most unlocked GSM Phones, Tablets, and Hotspots.', N'https://www.freedompop.com/', N'', N'Monday to Friday, 9 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "FreedomPop"}}, "Description": {"Value": {"en": "Requires an email and place to list as your physical address, $5 GSM SIM kit to start Free monthly plan, $17 a month for Premium plan. One option is compatible with most unlocked GSM AT&T and T-Mobile phones, and another is compatible with most unlocked GSM Phones, Tablets, and Hotspots.", "es": "Requiere un correo electrónico y un lugar para listar como su dirección física, kit SIM GSM de $5 para comenzar el plan mensual gratuito, $17 al mes para el plan Premium. Una opción es compatible con la mayoría de teléfonos GSM AT&T y T-Mobile desbloqueados, y otra es compatible con la mayoría de teléfonos GSM, tabletas y puntos de acceso desbloqueados."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 9 a.m. to 5 p.m.", "es": "Lunes a viernes de 9 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (108, N'G Street Oasis', N'Provides services for homeless families with children. To obtain services one must be registered in the program. Please call Gail at the phone above to register, or email gstreet@ccslc.org\\n\\nCOVID update: No day shelter or kitchen facilities or transitional housing.', N'https://www.ccslc.org/g-street-oasis', N'gstreet@ccslc.org', N'Monday, Wednesday, Friday, 9 a.m. to 3 p.m.', 1, N'{"Name": {"Value": {"en": "G Street Oasis"}}, "Description": {"Value": {"en": "Provides services for homeless families with children. To obtain services one must be registered in the program. Please call Gail at the phone above to register, or email gstreet@ccslc.org\\n\\nCOVID update: No day shelter or kitchen facilities or transitional housing.", "es": "Ofrece servicios para familias sin hogar con niños. Para obtener servicios uno debe estar registrado en el programa, por favor llame a Gail al teléfono de arriba para registrarse, o envíe un correo electrónico a gstreet@ccslc.org\\n\\nActualización de COVID: No hay refugio diurno o instalaciones de cocina ni viviendas de transición."}}, "HoursOfOperation": {"Value": {"en": "Monday, Wednesday, Friday, 9 a.m. to 3 p.m.", "es": "Lunes, miércoles, viernes de 9 a.m. a 3 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
