    (166, N'Love Project Food Pantry', N'This program distributes about 2-3 tons of food monthly to an average of 700 people.  ', N'https://midlanecares.com/veneta-love-project-food-pantry-garden/', N'midlanecares2@gmail.com', N'Our drive-through is open Mondays and Fridays 10:00 a.m-1:00 p.m. Wednesdays 2:00 p.m to 5:45 pm. Plan on arriving 15 minutes before closing time. ', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T20:33:48.673398'),
    (167, N'Low Income Energy Assistance Program (LIEAP)', N'Energy assistance for low-income seniors or disabled citizens of Lane County. See website for phone numbers and locations, depending on age and city of residence. Sign up for the waitlist in September.', N'https://www.lanecounty.org/government/county_departments/health_and_human_services/human_services_division/energy_and_weatherization_programs/general_public', N'', N'See website', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T20:30:24.706498'),
    (168, N'Lowell Food Pantry', N'Food pantry open the 1st and 3rd Tuesday of the month, from 2 p.m. to 5 p.m. Bread day and clothing bank on the 2nd and 4th Tuesday from 10 a.m. to 12 p.m.', N'https://www.ci.lowell.or.us/business-directory-listing/food-pantry', N'', N'First and third Tuesdays 2 to 5 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T20:36:24.596860'),
    (169, N'Lower McKenzie Community Resources', N'The McKenzie River Food Pantry provides a variety of fresh and shelf-stable groceries to low-income families and individuals who live in the 97413 or 97488 zip codes. The pantry is located in the new gym on the right-hand side of the parking lot at McKenzie High School.', N'https://mckenziecommunity.org/', N'contact@mckenziecommunity.org', N'2nd & 4th Tuesday of the month,  from 4:30 pm to 6:30 pm.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-15T05:30:40.001763'),
    (170, N'LTD Reduced Fare', N'LTD provides free bus fares for those 65 and older and reduced fares for those who are disabled. ', N'https://www.ltd.org/riding-the-bus/', N'', N'Weekdays, 7am – 6pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-15T05:37:30.984529'),
    (171, N'LTD RideSource', N'A program to provide residents with non-emergency medical transportation. Call the above numbers to get information about obtaining a transportation assessment. Call M-5 8-5 to set up a scheduled transport. RideSource does not provide same-day transport.', N'https://www.ltd.org/ridesource/', N'', N'Monday to Friday, 8 a.m. to 5 p.m., Saturday and Sunday from 11 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "LTD RideSource"}}, "Description": {"Value": {"en": "A program to provide residents with non-emergency medical transportation. Call the above numbers to get information about obtaining a transportation assessment. Call M-5 8-5 to set up a scheduled transport. RideSource does not provide same-day transport.\\n\\nCOVID Update: Only critical or essential trips are accepted; masks required at all times.", "es": "Un programa para ofrecer a los residentes transporte médico que no sea de emergencia. Llame a los números anteriores para obtener información sobre cómo obtener una evaluación de transporte. Llame al M-5 8-5 para programar un transporte programado. RideSource no ofrece transporte el mismo día.\\n\\nActualización COVID: Solo se aceptan viajes críticos o esenciales; máscaras necesarias en todo momento."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 5 p.m., Saturday and Sunday from 11 a.m. to 5 p.m.", "es": "Lunes a viernes de 8 a.m. a 5 p.m., sábados y domingos de 11 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-15T05:40:58.081735'),
