    (176, N'McKinney-Vento Liaison: Bethel School District', N'The McKinney-Vento Act is a federal law that ensures the rights of youth to go to school even when they are homeless or don’t have a permanent address. Every school district in the country is required to have McKinney-Vento liaisons who work to reduce barriers that prevent homeless youth from enrolling, attending, and succeeding in school; including transportation, residency requirements, school meals, and documentation requirements. McKinney-Vento liaisons also connect students and families to local support resources. Contact your local school district to request more information about McKinney-Vento supports.', N'https://www.bethelsd.org/programs/mckinney-vento-homeless-assistance', N'', N'', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T20:54:59.980776'),
    (177, N'McKinney-Vento Liaison: South Lane School District', N'The McKinney-Vento Act is a federal law that ensures the rights of youth to go to school even when they are homeless or don’t have a permanent address. Every school district in the country is required to have McKinney-Vento liaisons who work to reduce barriers that prevent homeless youth from enrolling, attending, and succeeding in school; including transportation, residency requirements, school meals, and documentation requirements. McKinney-Vento liaisons also connect students and families to local support resources. Contact your local school district to request more information about McKinney-Vento supports.', N'https://www.slane.k12.or.us/domain/125', N'Tessa.hart@southlane.k12.org.edu', N'', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T20:56:31.505107'),
