    (187, N'Multiple Sclerosis Foundation Emergency Assistance Program', N'Full or partial financial assistance for urgent needs related to rent and utilities, or medication for those diagnosed with Multiple Sclerosis.', N'https://msfocus.org/Get-Help.aspx', N'support@msfocus.org', N'Monday to Friday, 8:30am – 5:30pm  ', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-15T21:00:23.807340'),
    (188, N'NA (Narcotics Anonymous) Meetings', N'Helps one find an NA meeting near them. Meeting availability subject to change, check website.', N'http://lanecountyarea-na.org/', N'', N'All hours, every day', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-15T21:04:04.234591'),
    (189, N'Nar-Anon Family Groups', N'Support groups for family and friends affected by a loved one''s substance abuse. Call for meeting times and places. No dues or fees.', N'https://www.nar-anon.org/', N'', N'Monday to Friday 9 a.m. to 5 p.m. ', 1, N'{"Name": {"Value": {"en": "Nar-Anon Family Groups"}}, "Description": {"Value": {"en": "Support groups for family and friends affected by a loved one''s substance abuse. Call for meeting times and places. No dues or fees.\\n\\nCOVID Update: Some groups are returning to physical meetings, but others are still meeting virtually.", "es": "Grupos de apoyo para familiares y amigos afectados por el abuso de sustancias de un ser querido. Llame para conocer los horarios y lugares de las reuniones. Sin cuotas ni tarifas.\\n\\nActualización de COVID: algunos grupos están regresando a las reuniones físicas, pero otros aún se están reuniendo virtualmente."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday 9 a.m. to 5 p.m.", "es": "Lunes a viernes de 9 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-15T21:08:03.763704'),
    (190, N'National Alliance on Mental Illness Lane County (NAMI)', N'In-person and online meetings for individuals, family members, caregivers, and loved ones of individuals living with mental health condition. Open to the public, no proof of income or diagnosis required.  Call to register, or register online.', N'https://namilane.org/', N'', N'Monday- Wednesday 10am 3pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-15T21:10:55.268206'),
    (191, N'National Child Abuse Hotline', N'Provides counseling concerning child abuse 24/7 (interpretation available for 140 languages).', N'https://www.childhelp.org', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "National Child Abuse Hotline"}}, "Description": {"Value": {"en": "Provides counseling concerning child abuse 24/7 (interpretation available for 140 languages).", "es": "Ofrece asesoramiento sobre el abuso infantil las 24 horas del día, los 7 días de la semana (interpretación disponible para 140 idiomas)."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (192, N'National Clearinghouse for Alcohol & Drug Information (NCADI)', N'National resource for information about substance abuse prevention and addiction treatment. Free publications are available on its website.', N'https://store.samhsa.gov/', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "National Clearinghouse for Alcohol & Drug Information (NCADI)"}}, "Description": {"Value": {"en": "National resource for information about substance abuse prevention and addiction treatment. Free publications are available on its website.", "es": "Recurso nacional para obtener información sobre la prevención del abuso de sustancias y el tratamiento de adicciones. Las publicaciones gratuitas están disponibles en su sitio web."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (193, N'National Health Information Center', N'Helps connect health professionals and consumers to the organizations that can best answer their questions by providing up-to-date contact information for the most reliable sources.', N'https://health.gov/our-work/national-health-initiatives/health-literacy/resources/national-health-information-center', N'info@nhic.org', N'All hours, every day', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:09:21.158613'),
    (194, N'National Suicide Prevention Lifeline', N'Free and confidential counseling for those who are in a suicide crisis. Assistance in Spanish available; specific resources available for various communities (i.e. youth, Veterans, LGBTQ+, Deaf/Hard of Hearing, Native Americans, and more). Text or call 988.', N' https://988lifeline.org/', N'', N'All hours, every day', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:10:07.671106'),
    (195, N'New Hope Baptist Church', N'Free dinner on Wednesday evening during the school year.', N'https://www.newhopecreswell.com/', N'', N'Wednesday 5 to 6 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:10:51.699307'),
    (196, N'Nightingale Hosted Shelters', N'Temporary shelter and healthy supportive community for people who are unhoused. NHS provides Conestoga huts or tents, port-a-potties, and garbage and recycling. Apply online to get on the waiting list.', N'https://nightingaleshelters.org/', N'', N'Monday to Friday, 9 a.m. to 5 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:11:31.933389'),
    (197, N'NorseMen Village Apartments', N'Low income apartments for seniors (62 years and older) and disabled people. Norsemen is walking distance from old downtown Junction City, with proximity to cafes and shops, and close to City Hall and other services and was completely renovated in 2013. The Viking Sal Senior Center is also nearby. There is professional onsite management and maintenance who attend to the development’s upkeep. Food assistance available for residents. Some units ADA accessible. To apply for their program, call and request an application. ', N'https://www.homesforgood.org/find-a-home/site-details/10030', N'', N'Mon,Wed, Fri 8-5pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:13:18.052516'),
    (198, N'Northwest Abortion Access Fund', N'Provides abortion information and referral services over the phone, as well as funding for abortions and abortion access issues (transportation, childcare, lodging). You can leave a Spanish-language voicemail. Translation assistance available for other languages.', N'https://nwaafund.org/', N'info@nwaafund.org', N'They will return your call within 24 hours', 1, N'{"Name": {"Value": {"en": "Northwest Abortion Access Fund"}}, "Description": {"Value": {"en": "Provides abortion information and referral services over the phone, as well as funding for abortions and abortion access issues (transportation, childcare, lodging).\\n\\nYou can leave a Spanish-language voicemail. Translation assistance available for other languages.", "es": "Ofrece información sobre el aborto y servicios de referencia por teléfono, así como financiamiento para abortos y problemas de acceso al aborto (transporte, cuidado de niños, alojamiento).\\n\\nPuede dejar un mensaje de voz en español. Asistencia de traducción disponible para otros idiomas."}}, "HoursOfOperation": {"Value": {"en": "They will return your call within 24 hours", "es": "Ellos le devolverán la llamada dentro de las 24 horas, de lunes a viernes."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-16T02:17:58.129475'),
    (200, N'Oakridge Public Library', N'Public library with Wi-Fi in the parking lot. And clean filtered air in the event of wildfire smoke. Memberships are free for all Oakridge residents, and $20 for non-residents. ', N'https://www.ci.oakridge.or.us/library', N'', N'Mon 1-5, Tues 9-5, Wed 1-5, Thurs 9-5, Sat 10-2', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:19:02.420012'),
    (202, N'Occupy Medical', N'We offer medical, wound care, herbal medicine and emotional support. All services are free. On the first & third Saturday of each month at St. Vincent Dupaul Service Center, 450 Highway 99 N.  On the second & fourth Saturday of each month at Washington Jefferson Park.', N'http://occupy-medical.org/', N'occmednow@gmail.com', N'Saturday from 9am to 11am', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:20:18.168886'),
    (203, N'ODI Clinic: Adolescent & Family Services', N'Provides no-cost treatment for youth addiction (12-18) that includes cognitive behavioral approaches with active parent involvement. Families wishing to see a counselor at the OSLC location should call and ask for an appointment with Adolescent & Family Services. Students in the 4J & Bethel school districts can inquire with their school counselor about speaking to a AFS clinician.', N'https://www.odiclinic.org/afs/', N'', N'Call to schedule an appointment', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:21:14.376251'),
    (204, N'ODI Clinic: Centro Latino Americano', N'Provides treatment for youth addiction that includes cognitive behavioral and behavioral approaches with active parent involvement. Provides for the local Latino population social services, alcohol and addiction treatment, community health care, translation services for youth and adults. Spanish and English services provided.', N'https://centrolatinoamericano.org/', N'', N'Monday-Friday 9am to noon, 1pm to 6pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:22:37.535647'),
    (205, N'Operation Homefront', N'Providing assistance for Veterans in need. All financial needs must be documented. They provide for those qualified: financial assistance, transitional housing, school supplies, holiday meals.', N'https://www.operationhomefront.org/', N'oregon@operationhomefront.org', N'All hours, every day', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-16T02:39:43.284020'),
    (206, N'Ophelia’s Place', N'Eugene Support and empowerment center for girl-identified youth (ages 10 to 18). Counseling by appointment. Please call for orientation information. Spanish speakers available.', N'http://opheliasplace.net/', N'info@opheliansplace.net', N'Monday to Thursday 10 a.m. to 6 p.m.; Drop in hours 3pm-6pm Monday to Thursday', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-16T02:43:43.683106'),
    (207, N'Opportunity Village', N'Transitional shelter for adults, singles and couples. 30 Micro Homes. When the application process becomes available it will be on their website. Each individual village does their own application process.', N'https://www.squareonevillages.org/', N'info@squareonevillages.org', N'Every day, 10 a.m. to 5 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:30:18.626436'),
    (208, N'Options Counseling Services', N'Provides behavioral health, family preservation, and family supportive services to families and individuals. ', N'https://wp.options.org/', N'options@options.org', N'Monday to Friday, 8:30 a.m. to 5 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:32:02.003686'),
    (209, N'Oregon Abuse Hotline for Children & Adults', N'Report suspected child abuse to DHS. Be ready to provide identifying information and the whereabouts of the child if known. TTY/Voice: 503-945-5811 Confirmed Information', N'https://www.oregon.gov/DHS/abuse/Pages/index.aspx', N'', N'All hours, every day', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:34:15.633667'),
    (210, N'Oregon Department of Human Services - 11th Ave', N'Apply for state- and federally-funded services. Food benefits (SNAP), cash assistance (TANF), domestic violence services, child welfare services, health benefits (OHP), senior citizens services, Employment Related day Care(ERDC). Referrals to other services. You can also apply for all these services at: One Customer Service Center 1-800-699-9075 or online at https://one.oregon.gov English and Spanish spoken translation services available to assist in receiving services. Public Restrooms Available.', N'https://www.oregon.gov/DHS/Offices/Pages/index.aspx', N'', N'Monday to Friday, 7 a.m. to 6 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:38:49.578549'),
    (211, N'Oregon Department of Human Services - Cottage Grove', N'State- and federally-funded services. Food benefits, employment services, cash assistance, domestic violence services, child welfare services, senior citizens services. You can also apply for all these services online at: https://govstatus.egov.com/or-dhs-benefits. ', N'https://www.oregon.gov/DHS/Offices/Pages/index.aspx', N'', N'Monday to Friday, 8 a.m. to 5 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-16T03:14:28.528515'),
