    (214, N'Oregon Department of Human Services - Mckenzie', N'State- and federally-funded services. Food benefits (SNAP), employment services, cash assistance (TANF), domestic violence services, child welfare services, health benefits (OHP), senior citizens services. You can also apply for all these services. One Customer Service Center 1-800-699-9075 or online at https://one.oregon.gov English and Spanish spoken translation services available to assist in receiving services Public phone, computer, print, fax, bathrooms, and children’s play area.', N'https://www.oregon.gov/DHS/Offices/Pages/index.aspx', N'', N'Monday to Friday, 8 a.m. to 5 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:46:10.335330'),
    (215, N'Oregon Department of Human Services- 30th St', N'State- and federally-funded services. Food benefits (SNAP), employment services, cash assistance (TANF), domestic violence services, child welfare services, health benefits (OHP), senior citizens services, Employment Related Cay Care (ERDC). One Customer Service Center 18006999075 or online at https://one.oregon.gov English and Spanish spoken translation services available to assist in receiving services. Public restrooms, phones, computers. ', N'https://www.oregon.gov/DHS/Offices/Pages/index.aspx', N'', N'Monday to Friday, 8 a.m. to 8 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:52:05.143258'),
    (216, N'Oregon Department of Motor Vehicles - Eugene', N'Provides all forms of driver licensing, vehicle titles and registration, MCTD and highway permits. For disabled parking placards, pick up an application, get a doctor''s signature, and return the application. Homeless individuals may use shelter location with letter as proof of address for obtaining IDs.', N'https://www.oregon.gov/ODOT/DMV/Pages/index.aspx', N'', N' Monday, Tuesday, Thursday, Friday 8 a.m. to 5 p.m. Wed 10-5', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:55:03.360625'),
    (217, N'Oregon Department of Motor Vehicles - Florence', N'Provides all forms of driver licensing, vehicle titles and registration, MCTD and highway permits. For disabled parking placards, pick up an application, get a doctor''s signature, and return the application. Homeless individuals may use shelter location with letter as proof of address for obtaining IDs.', N'https://www.oregon.gov/ODOT/DMV/Pages/index.aspx', N'', N'Monday to Friday, 9 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "Oregon Department of Motor Vehicles - Florence"}}, "Description": {"Value": {"en": "Provides all forms of driver licensing, vehicle titles and registration, MCTD and highway permits. For disabled parking placards, pick up an application, get a doctor''s signature, and return the application. Homeless individuals may use shelter location with letter as proof of address for obtaining IDs.\\n\\nCOVID Update: By appointment only through the website. All patrons must be six feet apart, wear masks, and wait outside the building. One person per appointment. There are multiple locations on the website.", "es": "Ofrece todas las formas de licencias de conducir, títulos y registros de vehículos, MCTD y permisos de carreteras. Para carteles de estacionamiento para discapacitados, recoja una solicitud, obtenga la firma de un médico y devuelva la solicitud. Las personas sin hogar pueden usar la ubicación del refugio con una carta como prueba de dirección para obtener identificaciones.\\n\\nActualización COVID: Con cita previa solo a través del sitio web. Todos los usuarios deben estar separados por seis pies, usar máscaras y esperar afuera del edificio. Una persona por cita. Hay varias ubicaciones en el sitio web."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 9 a.m. to 5 p.m.", "es": "Lunes a viernes de 9 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-16T04:11:03.847873'),
    (218, N'Oregon Department of Motor Vehicles - Springfield', N'Provides all forms of driver licensing, vehicle titles and registration, MCTD and highway permits. For disabled parking placards, pick up an application, get a doctor''s signature, and return the application. Homeless individuals may use shelter location with letter as proof of address for obtaining IDs.', N'https://www.oregon.gov/ODOT/DMV/Pages/index.aspx', N'', N' Monday, Tuesday, Thursday, Friday 9 a.m. to 5 p.m. Wednesday 10-5', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T21:59:02.661651'),
    (219, N'Oregon Family Support Network', N'Support for families raising a youth with emotional, behavioral, or mental health challenges (no diagnosis needed). Check website or text “safe” + city, state and zip code to 44357 to find a location. ', N'http://www.ofsn.org/', N'', N'Monday to Friday, 8:30 a.m. to 5 p.m. (best to call first)', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-16T04:29:07.883473'),
    (220, N'Oregon Health Plan', N'Apply for Oregon Health Plan online.', N'https://www.oregon.gov/oha/HSD/OHP/Pages/Apply.aspx', N'', N'Every day, 8 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "Oregon Health Plan"}}, "Description": {"Value": {"en": "Apply for Oregon Health Plan online.", "es": "Solicite el Plan de Salud de Oregon en línea."}}, "HoursOfOperation": {"Value": {"en": "Every day, 8 a.m. to 5 p.m.", "es": "Todos los días de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (221, N'Oregon Helps! Social Service Eligibility Calculator', N'This free web service can tell you whether your family is eligible for 33 programs and assistance, including Food Stamps, Oregon Health Plan, Employment Related Day Care (ERDC), Temporary Assistance for Needy Families (TANF), Federal Housing Assistance, Low-Income Home Energy Assistance Program (LIEAP), federal and state Earned Income Tax Credits, Oregon''s Working Family Tax Credit, Individual Development Accounts (IDAs), National School Lunch Program, Women, Infants, and Children Nutrition Program (WIC), and Emergency Food.', N'http://oregonhelps.211info.org/', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Oregon Helps! Social Service Eligibility Calculator"}}, "Description": {"Value": {"en": "This free web service can tell you whether your family is eligible for 33 programs and assistance, including Food Stamps, Oregon Health Plan, Employment Related Day Care (ERDC), Temporary Assistance for Needy Families (TANF), Federal Housing Assistance, Low-Income Home Energy Assistance Program (LIEAP), federal and state Earned Income Tax Credits, Oregon''s Working Family Tax Credit, Individual Development Accounts (IDAs), National School Lunch Program, Women, Infants, and Children Nutrition Program (WIC), and Emergency Food.", "es": "Este servicio web gratuito puede decirle si su familia es elegible para 33 programas y asistencia, incluidos Cupones para Alimentos, Plan de Salud de Oregon, Guardería Relacionada con el Empleo (ERDC), Asistencia Temporal para Familias Necesitadas (TANF), Asistencia Federal para Vivienda, Personas de Bajos Ingresos Programa de Asistencia de Energía para el Hogar (LIEAP), Créditos Tributarios por Ingresos del Trabajo federales y estatales, Crédito Tributario para Familias Trabajadoras de Oregon, Cuentas de Desarrollo Individual (IDA), Programa Nacional de Almuerzos Escolares, Programa de Nutrición para Mujeres, Bebés y Niños (WIC) y Alimentos de Emergencia."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000');
