INSERT INTO dbo.[Provider] ([ProviderId], [Name], [Description], [WebAddress], [EmailAddress], [HoursOfOperation], [IsActive], [l10N], [CreatedBy], [CreatedOn], [ModifiedBy], [ModifiedOn]) VALUES
    (1, N'1st Way Mobile Unit - Tuesday', N'Provides free pregnancy tests, ultrasounds, and counseling. Pregnant women can receive referrals for health services. Can refer for insurance information and health services.', N'https://www.1st-way.org/', N'firstwayeugene@gmail.com', N'Tuesday 11 a.m. - 2 p.m. ', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'AdamW', '2024-09-21T20:21:13.754086'),
    (2, N'1st Way Mobile Unit - Wednesday', N'Provides free pregnancy tests, ultrasounds, and counseling. Pregnant women can receive referrals for health services. Can refer for insurance information and health services.', N'https://www.1st-way.org/', N'firstwayeugene@gmail.com', N'Wednesdays 11a.m. - 2 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'AdamW', '2024-09-21T20:25:08.526594'),
    (3, N'1st Way of Eugene', N'Provides baby and toddler clothes, baby wipes, diapers, and furniture for all without charge. Also provides free pregnancy tests, ultrasounds, and counseling. Pregnant women can receive referrals for health services. Can refer for insurance information and health services.', N'https://www.1st-way.org/', N'firstwayeugene@gmail.com', N'Monday, Tuesday and Wednesday, 10 a.m. to 1 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'AdamW', '2024-09-21T20:27:35.800730'),
    (4, N'15th Night', N'24/7 talk or chat hotline for youth. Provides rapid access to resources and emergency services, such as: clothing/shoes, personal care products, backpacks, food, housing specialist, transportation, doctor''s appointments, counseling, mentors/peer support/LGBTQIA2S+ support, youth advocate, application assistance, and library cards.', N'https://www.15thnight.org', N'info@15thNight.org', N'All hours, every day', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-05T22:51:50.178035'),
    (5, N'211 Info', N'211 info helps people identify, navigate, and connect with local resources such as: Child Care and Parenting, Utility Assistance, Emergency Management, Food, Health, Housing & Shelter.Text your zip code to 898211 (TXT211). One can also search the resource database on the website. To ask about resources in your area: call, text, or email (help@211info.org). You should receive a response within 24 hours. ', N'https://www.211info.org/', N'help@211info.org', N'24/7, every day', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-08T00:49:39.216671'),
    (6, N'911', N'Emergencies only. 911 is for people to reach police, fire or emergency medical assistance from any phone in any location, without having to look up specific phone numbers.', N'https://www.911.gov/', N'', N'All hours, every day', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'AdamW', '2024-09-21T20:39:18.869787'),
    (7, N'Access the Law', N'Provides quality legal services for working and low income families and individuals. Fifty-dollar consultation. Provides free legal consultation for veterans once a month. (Free service only available from January-October.)', N'https://accessthelaw.org/', N'access@accessthelaw.org', N'Monday to Friday, 8 a.m. to 5 p.m. (out of office from noon to 1 p.m.)', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-06T01:36:06.613766'),
    (9, N'Alcoholics Anonymous (AA)', N'The AA intergroup office sells AA literature, helps locate local AA meetings, and provides 12-Step support; phone calls are answered 24/7. Meetings, services and, events are listed on the website. ', N'https://eviaaweb.org/', N'evi_office@eviaa.org', N'Monday to Friday, 9 a.m. to 5 p.m. Saturday and Sunday 9 a.m. to 4p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'AdamW', '2024-09-21T20:53:08.308264'),
    (10, N'Alton Baker Park Syringe Dropoff', N'Syringe drop off in blue box, no exchange', N'https://hivalliance.org/prevent/syringe-services/', N'', N'All hours, every day', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-06T01:53:24.155419'),
    (11, N'Alzheimer’s Association Helpline', N'Help for sufferers of dementia and their families or caregivers. Sometimes out of the office, but leave a number and they will call back. Spanish speakers available.', N'https://www.alz.org/help-support/resources/helpline', N'', N'All hours, every day', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-06T01:57:34.806268'),
    (12, N'American Civil Liberties Union of Oregon (ACLU)', N'ACLU is not a legal services organization and cannot respond to requests for legal help. Know Your Rights resources are available through their website. 
INSERT INTO dbo.[Provider] ([ProviderId], [Name], [Description], [WebAddress], [EmailAddress], [HoursOfOperation], [IsActive], [l10N], [CreatedBy], [CreatedOn], [ModifiedBy], [ModifiedOn]) VALUES
    (112, N'Goodwill Industries Job Connections', N'Call first. Provides employment and job search assistance for those who have barriers to employment. Workshops, job leads and employment opportunities are available.', N'https://goodwilljobconnection.org/', N'', N'Monday to Friday, 8 a.m. to 4 p.m.', 1, N'{"Name": {"Value": {"en": "Goodwill Industries Job Connections"}}, "Description": {"Value": {"en": "Call first. Provides employment and job search assistance for those who have barriers to employment. Workshops, job leads and employment opportunities are available.", "es": "Llame primero. Ofrece empleo y asistencia para la búsqueda de empleo para aquellos que tienen barreras de empleo. Se encuentran disponibles talleres, oportunidades laborales y oportunidades de empleo."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 4 p.m.", "es": "Lunes a viernes de 8 a.m. a 4 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (115, N'HIV Alliance - Cottage Grove Needle Exchange', N'Provides syringe exchange and harm reduction services as well as HIV and hepatitis C testing.', N'https://hivalliance.org/prevent/syringe-services/#syringe-exchange', N'prevention@allianceor.org for needle exchange information', N'Tuesdays  5:30 to 7 p.m.', 1, N'{"Name": {"Value": {"en": "HIV Alliance - Cottage Grove Needle Exchange"}}, "Description": {"Value": {"en": "Provides syringe exchange and harm reduction services as well as HIV and hepatitis C testing.", "es": "Ofrece servicios de intercambio de jeringas y reducción de daños, así como pruebas de VIH y hepatitis C."}}, "HoursOfOperation": {"Value": {"en": "Tuesdays 5:30 to 7 p.m.", "es": "Martes de 5:30 a 7 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (116, N'HIV Alliance Community', N'Syringe drop off, needle exchange services. Helps people living with HIV/AIDS to stabilize and maintain their health through support, advocacy, referral services and emergency financial assistance for basic needs like housing, food, electricity and heat, and medication. Call for services by phone; no in-person appointments. HIV and hepatitis C testing for high-risk individuals.', N'https://hivalliance.org/prevent/syringe-services/', N'prevention@allianceor.org for needle exchange/syringe drop off information', N'Monday to Friday, 10 a.m. to 2 p.m.', 1, N'{"Name": {"Value": {"en": "HIV Alliance Community"}}, "Description": {"Value": {"en": "Syringe drop off, needle exchange services. Helps people living with HIV/AIDS to stabilize and maintain their health through support, advocacy, referral services and emergency financial assistance for basic needs like housing, food, electricity and heat, and medication. Call for services by phone; no in-person appointments. HIV and hepatitis C testing for high-risk individuals.", "es": "Entrega de jeringas, servicios de cambio de agujas. Ayuda a las personas que viven con el VIH / SIDA a estabilizar y mantener su salud a través de apoyo, defensa, servicios de referencia y asistencia financiera de emergencia para necesidades básicas como vivienda, alimentos, electricidad y calefacción, y medicamentos. Llame para solicitar servicios por teléfono; sin citas en persona. Pruebas de VIH y hepatitis C para personas de alto riesgo."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 10 a.m. to 2 p.m.", "es": "Lunes a viernes de 10 a.m. a 2 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (117, N'HIV Alliance Outreach - Florence Needle Exchange', N'Needle exchange services provided to reduce hepatitis C and HIV in Lane County.', N'https://hivalliance.org/prevent/syringe-services/', N'prevention@allianceor.org for needle exchange information', N'1st and 3rd Fridays, 11 a.m. to 3 p.m.', 1, N'{"Name": {"Value": {"en": "HIV Alliance Outreach - Florence Needle Exchange"}}, "Description": {"Value": {"en": "Needle exchange services provided to reduce hepatitis C and HIV in Lane County.", "es": "Se ofrecen servicios de intercambio de agujas para reducir la hepatitis C y el VIH en el condado de Lane."}}, "HoursOfOperation": {"Value": {"en": "1st and 3rd Fridays, 11 a.m. to 3 p.m.", "es": "1er y 3er viernes de 11 a.m. a 3 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (118, N'HIV Alliance Outreach - Monday Needle Exchange', N'Needle exchange services provided to reduce hepatitis C and HIV in Lane County, on the following schedule:', N'https://hivalliance.org/prevent/syringe-services/', N'prevention@allianceor.org for needle exchange information', N'Mondays 6 to 7:30 p.m.', 1, N'{"Name": {"Value": {"en": "HIV Alliance Outreach - Monday Needle Exchange"}}, "Description": {"Value": {"en": "Needle exchange services provided to reduce hepatitis C and HIV in Lane County, on the following schedule:", "es": "Se ofrecen servicios de intercambio de agujas para reducir la hepatitis C y el VIH en el condado de Lane, en el siguiente horario:"}}, "HoursOfOperation": {"Value": {"en": "Mondays 6 to 7:30 p.m.", "es": "Lunes de 6 a 7:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (120, N'HIV Alliance Outreach - Springfield Needle Exchange', N'Needle exchange services provided to reduce hepatitis C and HIV in Lane County.', N'https://hivalliance.org/prevent/syringe-services/', N'prevention@allianceor.org for needle exchange info', N'Thursdays 6 to 7:30 p.m.', 1, N'{"Name": {"Value": {"en": "HIV Alliance Outreach - Springfield Needle Exchange"}}, "Description": {"Value": {"en": "Needle exchange services provided to reduce hepatitis C and HIV in Lane County.", "es": "Se ofrecen servicios de intercambio de agujas para reducir la hepatitis C y el VIH en el condado de Lane."}}, "HoursOfOperation": {"Value": {"en": "Thursdays 6 to 7:30 p.m.", "es": "Jueves 6 a 7:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (121, N'HIV Alliance Outreach - Thursday Needle Exchange', N'Needle exchange services provided to reduce Hepatitis C and HIV in Lane County.', N'https://hivalliance.org/prevent/syringe-services/', N'prevention@allianceor.org for needle exchange information', N'Thursdays from 9:45 a.m. to noon', 1, N'{"Name": {"Value": {"en": "HIV Alliance Outreach - Thursday Needle Exchange"}}, "Description": {"Value": {"en": "Needle exchange services provided to reduce Hepatitis C and HIV in Lane County.", "es": "Se ofrecen servicios de intercambio de agujas para reducir la hepatitis C y el VIH en el condado de Lane."}}, "HoursOfOperation": {"Value": {"en": "Thursdays from 9:45 a.m. to noon", "es": "Jueves de 9:45 a.m. a mediodía"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (122, N'HIV Alliance Outreach - Wednesday Needle Exchange', N'Needle exchange services provided to reduce hepatitis C and HIV in Lane County.', N'https://hivalliance.org/prevent/syringe-services/', N'prevention@allianceor.org for needle exchange information', N'Wednesdays 6 to 7:30 p.m.', 1, N'{"Name": {"Value": {"en": "HIV Alliance Outreach - Wednesday Needle Exchange"}}, "Description": {"Value": {"en": "Needle exchange services provided to reduce hepatitis C and HIV in Lane County.", "es": "Se ofrecen servicios de intercambio de agujas para reducir la hepatitis C y el VIH en el condado de Lane."}}, "HoursOfOperation": {"Value": {"en": "Wednesdays 6 to 7:30 p.m.", "es": "Miércoles de 6 a 7:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (123, N'HIV Alliance, Inc. - Case Management', N'Helps people living with HIV/AIDS to stabilize and maintain their health through support, advocacy, referral services and emergency financial assistance for basic needs like housing, food, electricity and heat, and medication. Call for services by phone; no in-person appointments. HIV and hepatitis C testing for high-risk individuals.', N'https://hivalliance.org/', N'', N'Monday to Friday, 9 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "HIV Alliance, Inc. - Case Management"}}, "Description": {"Value": {"en": "Helps people living with HIV/AIDS to stabilize and maintain their health through support, advocacy, referral services and emergency financial assistance for basic needs like housing, food, electricity and heat, and medication. Call for services by phone; no in-person appointments. HIV and hepatitis C testing for high-risk individuals.", "es": "Ayuda a las personas que viven con el VIH / SIDA a estabilizar y mantener su salud a través de apoyo, defensa, servicios de referencia y asistencia financiera de emergencia para necesidades básicas como vivienda, alimentos, electricidad y calefacción, y medicamentos. Llame para solicitar servicios por teléfono; sin citas en persona. Pruebas de VIH y hepatitis C para personas de alto riesgo."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 9 a.m. to 5 p.m.", "es": "Lunes a viernes de 9 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (124, N'HIV Alliance, Inc. - HIV and Hepatitis C Testing', N'Offers free HIV and hepatitis C testing for high risk individuals. Results are available in 20 minutes.', N'https://hivalliance.org/', N'', N'Monday 3 to 7 p.m.; Tuesday 5 to 7 p.m.; Thursday 6 to 8 p.m.; Friday 1 to 5 p.m.', 1, N'{"Name": {"Value": {"en": "HIV Alliance, Inc. - HIV and Hepatitis C Testing"}}, "Description": {"Value": {"en": "Offers free HIV and hepatitis C testing for high risk individuals. Results are available in 20 minutes.", "es": "Ofrece pruebas gratuitas de VIH y hepatitis C para personas de alto riesgo. Los resultados están disponibles en 20 minutos."}}, "HoursOfOperation": {"Value": {"en": "Monday 3 to 7 p.m.; Tuesday 5 to 7 p.m.; Thursday 6 to 8 p.m.; Friday 1 to 5 p.m.", "es": "Lunes 3 a 7 p.m.; martes 5 a 7 p.m.; jueves 6 a 8 p.m.; viernes 1 a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (125, N'Homeownership Preservation Foundation', N'Referrals and counseling provided for homeowners facing foreclosure.', N'https://homeownershippreservation.org', N'', N'Call for hours', 1, N'{"Name": {"Value": {"en": "Homeownership Preservation Foundation"}}, "Description": {"Value": {"en": "Referrals and counseling provided for homeowners facing foreclosure.", "es": "Se ofrecen referencias y asesoramiento para propietarios que enfrentan una ejecución hipotecaria."}}, "HoursOfOperation": {"Value": {"en": "Call for hours", "es": "Llame por horas"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (126, N'Homes For Good Agency Lane County', N'Rental assistance program, including sign-up for Section 8. Complete a housing application when the wait list is open.\\n\\nCOVID Update: No drop in. Please call.', N'https://homesforgood.org/', N'paperwork@homesforgood.org', N'Monday to Thursday, 8 a.m. to 4 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'DavidD', '2024-09-21T22:03:44.627438'),
    (127, N'Hosea Youth Services', N'Drop-in day access center for homeless and displaced youth 16-24 including job search, meals, showers, laundry, clothing, and personal hygiene items. Dinner served to go at 5 p.m.', N'http://www.hoseayouth.org', N'', N'Monday to Thursday, 1 p.m. to 6:30 p.m.', 1, N'{"Name": {"Value": {"en": "Hosea Youth Services"}}, "Description": {"Value": {"en": "Drop-in day access center for homeless and displaced youth 16-24 including job search, meals, showers, laundry, clothing, and personal hygiene items. Dinner served to go at 5 p.m.", "es": "Centro de acceso diurno para jóvenes sin hogar y desplazados de 16 a 24 años que incluye búsqueda de trabajo, comidas, duchas, lavandería, ropa y artículos de higiene personal. La cena se sirve para llevar a las 5 p.m."}}, "HoursOfOperation": {"Value": {"en": "Monday to Thursday, 1 p.m. to 6:30 p.m.", "es": "Lunes a jueves de 1 a 6:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (128, N'Hourglass Community Crisis Center', N'Hourglass Community Crisis Center serves adults residing in Lane County who are in need of short-term, mental health crisis assessment and stabilization, but do not require the medical capabilities of an acute care hospital or longer-term residential care. Hourglass Community Crisis Center welcomes individuals to walk in when they need it, or they can be referred by local law enforcement and other community partners due to a mental health crisis.', N'http://www.columbiacare.org/hourglass-community-crisis-center.html', N'', N'24/7', 1, N'{"Name": {"Value": {"en": "Hourglass Community Crisis Center"}}, "Description": {"Value": {"en": "Hourglass Community Crisis Center serves adults residing in Lane County who are in need of short-term, mental health crisis assessment and stabilization, but do not require the medical capabilities of an acute care hospital or longer-term residential care. Hourglass Community Crisis Center welcomes individuals to walk in when they need it, or they can be referred by local law enforcement and other community partners due to a mental health crisis.", "es": ""}}, "HoursOfOperation": {"Value": {"en": "24/7", "es": ""}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (129, N'Housing and Urban Development', N'HUD takes on cases when housing rights have been violated. Make a complaint on the website or by phone.', N'https://www.hud.gov/program_offices/fair_housing_equal_opp/online-complaint', N'', N'Monday to Friday, 8:30 a.m. to 4:30 p.m.', 1, N'{"Name": {"Value": {"en": "Housing and Urban Development"}}, "Description": {"Value": {"en": "HUD takes on cases when housing rights have been violated. Make a complaint on the website or by phone.", "es": "HUD se ocupa de los casos en que se han violado los derechos a la vivienda. Presenta una queja en el sitio web o por teléfono."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8:30 a.m. to 4:30 p.m.", "es": "Lunes a viernes de 8:30 a.m. a 4:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (130, N'Shelter Care', N'ShelterCare provides a range of housing programs and services to individuals and families who are experiencing, or on the verge of, homelessness.', N'http://www.sheltercare.org/', N'scadmin@sheltercare.org', N'Monday to Friday, 8:30 a.m. to 4:30 p.m.', 1, N'{"Name": {"Value": {"en": "Housing Services for Families (ShelterCare)"}}, "Description": {"Value": {"en": "ShelterCare Housing Services for Families has some monies to assist families with children, the elderly and individuals with a disability to remain in their homes. Call the phone number to begin the application process.", "es": "ShelterCare Housing Services for Families tiene dinero para ayudar a las familias con niños, ancianos y personas con discapacidades a permanecer en sus hogares. Llame al número de teléfono para comenzar el proceso de solicitud."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8:30 a.m. to 4:30 p.m.", "es": "Lunes a viernes de 8:30 a.m. a 4:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-07-30T01:56:42.501731'),
    (131, N'Huerto de la Familia', N'Provides Latino families in Lane County with a plot of land to garden and provides education and training opportunities. Also possible to contact by email: info@huertodelafamilia.org', N'https://huertodelafamilia.org/', N'info@huertodelafamilia.org', N'', 1, N'{"Name": {"Value": {"en": "Huerto de la Familia"}}, "Description": {"Value": {"en": "Provides Latino families in Lane County with a plot of land to garden and provides education and training opportunities. Also possible to contact by email: info@huertodelafamilia.org", "es": "Ofrece a las familias latinas del condado de Lane una parcela de tierra para cultivar un huerto y brinda oportunidades de educación y capacitación. También es posible contactar por correo electrónico: info@huertodelafamilia.org"}}, "HoursOfOperation": {"Value": {"en": "", "es": ""}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (132, N'Integrated Health Clinics of Eugene', N'Services for opioid-addicted persons include: HIV/Hepatitis screening and counseling, TB testing, medication monitoring, medically-supervised detoxification, urine drug screens, treatment/relapse prevention planning, individual, and group counseling, referrals for educational, vocational and other ancillary services, prevention education, intervention, mentor program.', N'http://integratedclinics.com/', N'', N'Monday to Friday, 6 a.m. to 2:30 p.m; Saturday 7 to 9:30 a.m.', 1, N'{"Name": {"Value": {"en": "Integrated Health Clinics of Eugene"}}, "Description": {"Value": {"en": "Services for opioid-addicted persons include: HIV/Hepatitis screening and counseling, TB testing, medication monitoring, medically-supervised detoxification, urine drug screens, treatment/relapse prevention planning, individual, and group counseling, referrals for educational, vocational and other ancillary services, prevention education, intervention, mentor program.", "es": "Los servicios para las personas adictas a los opioides incluyen: detección y asesoramiento de VIH / Hepatitis, prueba de tuberculosis, control de medicamentos, desintoxicación supervisada por un médico, detección de drogas en orina, planificación de tratamiento / prevención de recaídas, asesoramiento individual, grupal y, referencias para servicios educativos, vocacionales y otros servicios auxiliares, educación preventiva, intervención, programa de mentores."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 6 a.m. to 2:30 p.m; Saturday 7 to 9:30 a.m.", "es": "Lunes a viernes de 6 a.m. a 2:30 p.m.; sábado de 7 a 9:30 a.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (133, N'Jewish Federation of Lane County - Jewish Family Services', N'Provides for Jewish individuals: counseling, assessment and problem-solving for seniors, families and children; information on community resources and activities; emergency aid.\\n\\nEnglish and Hebrew spoken.', N'https://jewishfedlc.org/jewish-family-services/', N'', N'Call for hours', 1, N'{"Name": {"Value": {"en": "Jewish Federation of Lane County - Jewish Family Services"}}, "Description": {"Value": {"en": "Provides for Jewish individuals: counseling, assessment and problem-solving for seniors, families and children; information on community resources and activities; emergency aid.\\n\\nEnglish and Hebrew spoken.", "es": "Ofrece a personas judías: asesoramiento, evaluación y resolución de problemas para personas mayores, familias y niños; información sobre recursos y actividades de la comunidad; ayuda de emergencia.\\n\\nSe habla inglés y hebreo."}}, "HoursOfOperation": {"Value": {"en": "Call for hours", "es": "Llame por horas"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (134, N'Junction City Local Aid', N'Food pantry available Tuesdays and Wednesdays 9 a.m. to 1 p.m., Thursdays 3 p.m. to 7 p.m., last Saturday of every month from 10 a.m. to noon. Prescription drug assistance, heating assistance (propane vouchers), bus passes, and clothing also available.', N'http://junctioncitylocalaid.org/', N'info@JunctionCityLocalAid.org', N'Tuesday and Wednesday 9 a.m. to 1 p.m. Thursday 3 to 7 p.m. and the last Saturday of every month, 10 a.m. to noon', 1, N'{"Name": {"Value": {"en": "Junction City Local Aid"}}, "Description": {"Value": {"en": "Food pantry available Tuesdays and Wednesdays 9 a.m. to 1 p.m., Thursdays 3 p.m. to 7 p.m., last Saturday of every month from 10 a.m. to noon. Prescription drug assistance, heating assistance (propane vouchers), bus passes, and clothing also available.", "es": "Despensa de alimentos disponible los martes y miércoles de 9 a.m. a 1 p.m. Jueves 3 p.m. a las 7 p.m. y el último sábado de cada mes de 10 a 12 horas. También está disponible asistencia con medicamentos recetados, asistencia con calefacción (vales de propano), pases de autobús y ropa."}}, "HoursOfOperation": {"Value": {"en": "Tuesday and Wednesday 9 a.m. to 1 p.m. Thursday 3 to 7 p.m. and the last Saturday of every month, 10 a.m. to noon", "es": "Martes y miércoles de 9 a.m. a 1 p.m.; jueves de 3 a 7 p.m .; y el último sábado de cada mes, de 10 a.m. a mediodía"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (135, N'Junction City Public Library', N'Library services. Computers, one hour at a time.', N'http://www.junctioncity.com/library.html', N'', N'Tuesday to Thursday, 11 a.m. to 6 p.m., Friday and Saturday, 10 a.m. to 4 p.m.', 1, N'{"Name": {"Value": {"en": "Junction City Public Library"}}, "Description": {"Value": {"en": "Library services. Computers, one hour at a time.", "es": "Servicios de biblioteca. Computadoras, una hora a la vez."}}, "HoursOfOperation": {"Value": {"en": "Tuesday to Thursday, 11 a.m. to 6 p.m., Friday and Saturday, 10 a.m. to 4 p.m.", "es": "Martes a jueves de 11 a 18 horas, viernes y sábado de 10 a 16 horas."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (136, N'Lane Community College Dental Clinic', N'Services include root canals and crowns, fillings, extractions, hygiene appointments, x-rays, and dentures. New patients call for an evaluation. No walk-in or immediate appointments available.', N'https://www.lanecc.edu/dentalclinic', N'', N'Monday to Friday, some Saturdays 8 a.m. to 5 (closed Friday during summer)', 1, N'{"Name": {"Value": {"en": "Lane Community College Dental Clinic"}}, "Description": {"Value": {"en": "Services include root canals and crowns, fillings, extractions, hygiene appointments, x-rays, and dentures. New patients call for an evaluation. No walk-in or immediate appointments available.", "es": "Los servicios incluyen endodoncias y coronas, empastes, extracciones, citas de higiene, radiografías y dentaduras postizas. Los pacientes nuevos requieren una evaluación. No hay citas disponibles de inmediato o sin cita previa."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, some Saturdays 8 a.m. to 5 (closed Friday during summer)", "es": "Lunes a viernes, algunos sábados de 8 a.m. a 5 (cerrado los viernes durante el verano)"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (137, N'Lane Community College Financial Aid', N'Provides information and assistance obtaining grants or financial aid to attend college.', N'https://www.lanecc.edu/financialaid', N'', N'Monday, Tuesday, Wednesday, Friday 8:30 a.m. to 5 p.m. and Thursday 10:30 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "Lane Community College Financial Aid"}}, "Description": {"Value": {"en": "Provides information and assistance obtaining grants or financial aid to attend college.", "es": "Ofrece información y ayuda para obtener subvenciones o ayuda financiera para asistir a la universidad."}}, "HoursOfOperation": {"Value": {"en": "Monday, Tuesday, Wednesday, Friday 8:30 a.m. to 5 p.m. and Thursday 10:30 a.m. to 5 p.m.", "es": "Lunes, martes, jueves de 8:30 a.m. a 5 p.m.; miércoles 10 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (138, N'Lane Community College GED Preparation', N'Finish your basic education with a GED certificate, which will prepare you for college. Many tests and courses are low cost or free for some students. Free tuition. Scholarships available for those in the program. Spanish language GED program available.', N'https://www.lanecc.edu/abse', N'', N'Monday to Thursday, 8:30 a.m. to 3:30 p.m. and Friday 8:30 a.m. to 2 p.m.', 1, N'{"Name": {"Value": {"en": "Lane Community College GED Preparation"}}, "Description": {"Value": {"en": "Finish your basic education with a GED certificate, which will prepare you for college. Many tests and courses are low cost or free for some students. Free tuition. Scholarships available for those in the program. Spanish language GED program available.\\n\\nCOVID Update: No transportation assistance while classes are online.", "es": "Termina tu educación básica con un certificado GED, que te preparará para la universidad. Muchos exámenes y cursos son de bajo costo o gratuitos para algunos estudiantes. Enseñanza gratis. Becas disponibles para aquellos en el programa. Programa de GED en español disponible.\\n\\nActualización de COVID: No hay asistencia de transporte mientras las clases estén en línea."}}, "HoursOfOperation": {"Value": {"en": "Monday to Thursday, 8:30 a.m. to 3:30 p.m. and Friday 8:30 a.m. to 2 p.m.", "es": "Lunes a jueves de 8:30 a.m. a 3:30 p.m.; viernes 8:30 a.m. a 2 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-08-09T17:52:16.219653'),
    (139, N'Lane Community College VA Educational Benefits Office', N'Certifies students eligible for VA educational benefits and can advise regarding qualifications, assist with determining educational goals and help with guiding students through navigating enrollment at LCC.', N'https://www.lanecc.edu/esfs/veterans-education-certification-information', N'vaedbenefits@lanecc.edu', N'See website for current hours', 1, N'{"Name": {"Value": {"en": "Lane Community College VA Educational Benefits Office"}}, "Description": {"Value": {"en": "Certifies students eligible for VA educational benefits and can advise regarding qualifications, assist with determining educational goals and help with guiding students through navigating enrollment at LCC.", "es": "Certifica a los estudiantes elegibles para los beneficios educativos de VA y puede asesorar sobre las calificaciones, ayudar a determinar los objetivos educativos y ayudar a guiar a los estudiantes a través de la navegación en la inscripción en LCC."}}, "HoursOfOperation": {"Value": {"en": "See website for current hours", "es": "Consulte el sitio web para conocer el horario actual"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (140, N'Lane County District Attorney''s Office', N'Provides assistance, criminal-justice education, guidance and support to crime victims. Services include crisis intervention, securing emergency assistance, case status notification, property return, community resource and referral, and court accompaniment. Also assists victims with application for crime victim''s compensation benefits.', N'https://lanecounty.org/https://lanecounty.org/government/county_departments/district_attorney_s_office', N'', N'Monday to Friday, 8 a.m. to 5 p.m. (out of office from noon to 1 p.m.)', 1, N'{"Name": {"Value": {"en": "Lane County District Attorney''s Office"}}, "Description": {"Value": {"en": "Provides assistance, criminal-justice education, guidance and support to crime victims. Services include crisis intervention, securing emergency assistance, case status notification, property return, community resource and referral, and court accompaniment. Also assists victims with application for crime victim''s compensation benefits.", "es": "Ofrece asistencia, educación en justicia penal, orientación y apoyo a las víctimas de delitos. Los servicios incluyen intervención en crisis, obtención de asistencia de emergencia, notificación del estado del caso, devolución de propiedad, recursos comunitarios y derivación, y acompañamiento judicial. También ayuda a las víctimas con la solicitud de beneficios de compensación para víctimas de delitos."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 5 p.m. (out of office from noon to 1 p.m.)", "es": "Lunes a viernes de 8 a.m. a 5 p.m. (fuera de la oficina desde el mediodía hasta las 1 p.m.)"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (141, N'Lane County Dovetail Program', N'Navigation services for those who are having difficulty in finding services in Lane County.\\n\\nCOVID Update: Call to make an appointment.', N'https://www.oregonpublichealth.org/assets/2019_Slides/Dovetail%20Program%20OPHA%202019.pdf', N'', N'Call to make appointment', 1, N'{"Name": {"Value": {"en": "Lane County Dovetail Program"}}, "Description": {"Value": {"en": "Navigation services for those who are having difficulty in finding services in Lane County.\\n\\nCOVID Update: Call to make an appointment.", "es": "Servicios de navegación para aquellos que tienen dificultades para encontrar servicios en el condado de Lane.\\n\\nActualización COVID: Llame para hacer una cita."}}, "HoursOfOperation": {"Value": {"en": "Call to make appointment", "es": "Llamar para concertar cita"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (142, N'Lane County Energy Programs', N'Provides information and referrals for energy and weatherization programs available in Lane County. The website has the basic guidelines and a list of the different programs.', N'https://lanecounty.org/https://lanecounty.org/government/county_departments/health_and_human_services/human_services_division/energy_and_weatherization_programs', N'', N'Call for appointment', 1, N'{"Name": {"Value": {"en": "Lane County Energy Programs"}}, "Description": {"Value": {"en": "Provides information and referrals for energy and weatherization programs available in Lane County. The website has the basic guidelines and a list of the different programs.\\n\\nCOVID Update: Call the number for an appointment; no drop-in appointments.", "es": "Ofrece información y referencias a programas de energía y climatización disponibles en el condado de Lane. El sitio web tiene las pautas básicas y una lista de los diferentes programas.\\n\\nActualización de COVID: llame al número para programar una cita, sin citas sin cita previa."}}, "HoursOfOperation": {"Value": {"en": "Call for appointment", "es": "Llame para una cita"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-08-11T01:58:55.040579'),
    (143, N'Lane County Legal Aid - Oregon Law Center', N'Provides legal services for low-income clients, civil matters, housing services, family law services for survivors of domestic and sexual abuse, assistance with immigration, foreclosures, and expungements. Assistance obtaining other public benefits.', N'http://www.lclac.org/', N'', N'Monday to Friday, 9 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "Lane County Legal Aid - Oregon Law Center"}}, "Description": {"Value": {"en": "Provides legal services for low-income clients, civil matters, housing services, family law services for survivors of domestic and sexual abuse, assistance with immigration, foreclosures, and expungements. Assistance obtaining other public benefits.", "es": "Ofrece servicios legales para clientes de bajos ingresos, asuntos civiles, servicios de vivienda, servicios de derecho familiar para sobrevivientes de abuso doméstico y sexual, asistencia con inmigración, ejecuciones hipotecarias y eliminación de antecedentes penales. Asistencia para obtener otros beneficios públicos."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 9 a.m. to 5 p.m.", "es": "Lunes a viernes de 9 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (144, N'Lane County Medical Examiner', N'The Medical Examiner investigates deaths and provide information about cause of death to next-of-kin. The website has a list of funeral homes and cremation services. The Medical Examiner’s office cannot make a recommendation of a funeral home for you. If you call the Medical Examiner, you first speak to the administrative assistant of the District Attorney.', N'https://www.oregon.gov/osp/programs/pages/med.aspx', N'', N'Monday to Friday, 9 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "Lane County Medical Examiner"}}, "Description": {"Value": {"en": "The Medical Examiner investigates deaths and provide information about cause of death to next-of-kin. The website has a list of funeral homes and cremation services. The Medical Examiner’s office cannot make a recommendation of a funeral home for you. If you call the Medical Examiner, you first speak to the administrative assistant of the District Attorney.", "es": "El médico forense investiga las muertes y ofrece información sobre la causa de la muerte a los familiares más cercanos. El sitio web tiene una lista de funerarias y servicios de cremación. La oficina del médico forense no puede recomendarle una funeraria. Si llama al médico forense, primero hable con el asistente administrativo del fiscal de distrito."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 9 a.m. to 5 p.m.", "es": "Lunes a viernes de 9 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-08-11T02:16:45.007793'),
    (145, N'Lane County Methadone Treatment Program', N'Provides outpatient chemical dependency treatment for adults with opiate addictions. For information in Spanish, please call (541) 682-4464.', N'https://lanecounty.org/government/county_departments/health_and_human_services/behavioral_health/methadone_treatment_program', N'', N'Monday to Friday, 6 a.m. to 10 a.m.; Saturday and Sunday, 7 a.m. to 10 a.m.', 1, N'{"Name": {"Value": {"en": "Lane County Methadone Treatment Program"}}, "Description": {"Value": {"en": "Provides outpatient chemical dependency treatment for adults with opiate addictions. For information in Spanish, please call (541) 682-4464.", "es": "Ofrece tratamiento ambulatorio de dependencia química para adultos con adicciones a opiáceos. Para obtener información en español, llame al (541) 682-4464."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 6 a.m. to 10 a.m.; Saturday and Sunday, 7 a.m. to 10 a.m.", "es": "Lunes a viernes de 6 a.m. a 10 a.m.; sábados y domingos de 7 a.m. a 10 a.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (146, N'Lane County Mutual Aid', N'Referrals for emergency financial assistance, food or grocery delivery. Please contact us through the website or by email: info@lanemutualaid.org', N'https://lanemutualaid.org/', N'Lanemutualaid@gmail.com', N'Call or email for availablity ', 1, N'{"Name": {"Value": {"en": "Lane County Mutual Aid"}}, "Description": {"Value": {"en": "Referrals for emergency financial assistance, food or grocery delivery. Please contact us through the website or by email: info@lanemutualaid.org", "es": "Referencias para asistencia financiera de emergencia, comida o entrega de comestibles. Póngase en contacto con nosotros a través del sitio web o por correo electrónico: info@lanemutualaid.org"}}, "HoursOfOperation": {"Value": {"en": "Call or email for availablity", "es": "Llame o envíe un correo electrónico para conocer la disponibilidad"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (147, N'Lane County Police Non-Emergency Line', N'Lane County Police non-emergency line.', N'https://www.lanecounty.org/https://www.lanecounty.org/government/county_departments/sheriff_s_office', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Lane County Police Non-Emergency Line"}}, "Description": {"Value": {"en": "Lane County Police non-emergency line.", "es": "Línea de no emergencia de la policía del condado de Lane"}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (148, N'Lane County Public Health Services', N'Testing for tuberculosis and sexually transmitted diseases. Immunizations provided. Accepts Oregon Health Plan.', N'https://lanecounty.org/', N'', N'Monday to Friday, 8 a.m. to 5 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'DavidD', '2024-09-21T22:30:02.745037'),
    (149, N'Lane County Veteran Service Office', N'Case management for vets, including filing for disability claims, obtaining military records, applying for VA Health Care, education benefits and surviving spouse benefits.', N'http://lanecounty.org/?pageId=4133203', N'', N'Monday to Friday, 8 a.m. to 3 p.m. (closed noon to 1 p.m.)', 1, N'{"Name": {"Value": {"en": "Lane County Veteran Service Office"}}, "Description": {"Value": {"en": "Case management for vets, including filing for disability claims, obtaining military records, applying for VA Health Care, education benefits and surviving spouse benefits.\\n\\nCOVID Update: Not available for in-person appointments.", "es": "Gestión de casos para veterinarios, incluida la presentación de reclamaciones por discapacidad, la obtención de registros militares, la solicitud de VA Health Care, los beneficios educativos y los beneficios para el cónyuge sobreviviente.\\n\\nActualización de COVID: no disponible para citas en persona."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 3 p.m. (closed noon to 1 p.m.)", "es": "Lunes a viernes de 8 a.m. a 3 p.m. (cerrado desde el mediodía hasta la 1 p.m.)"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-08-11T02:42:42.079465'),
    (150, N'Lane County Vital Records', N'Birth and death certificates for births and deaths in Lane County within five months of the event. Fill out the form at the drop box at the physical address or send an email. After five months, the certificates must be obtained by the state.', N'https://lanecounty.org/government/county_departments/health_and_human_services/public_health/birth___death_certificates', N'vitalrecords@lanecounty.gov', N'Monday to Friday, 9 a.m. to 4:30 p.m. ', 1, N'{"Name": {"Value": {"en": "Lane County Vital Records"}}, "Description": {"Value": {"en": "Birth and death certificates for births and deaths in Lane County within five months of the event. Fill out the form at the drop box at the physical address or send an email. After five months, the certificates must be obtained by the state.", "es": "Actas de nacimiento y defunción de nacimientos y defunciones en el condado de Lane dentro de los cinco meses posteriores al evento. Complete el formulario en el buzón de la dirección física o envíe un correo electrónico. Después de cinco meses, los certificados deben ser obtenidos por el estado."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 9 a.m. to 4:30 p.m.", "es": "Lunes a viernes, de 9 a.m. a 4:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (151, N'Lane Electric Member Assistance Program', N'This energy assistance program helps Lane Electric Cooperative (LEC) members that are falling behind pay their LEC bill, up to $250.', N'https://laneelectric.com/', N'', N'Monday to Thursday, 7:30 a.m. to 5:30 p.m.', 1, N'{"Name": {"Value": {"en": "Lane Electric Member Assistance Program"}}, "Description": {"Value": {"en": "This energy assistance program helps Lane Electric Cooperative (LEC) members that are falling behind pay their LEC bill, up to $250.\\n\\nCOVID Update: By appointment only.", "es": "Este programa de asistencia energética ayuda a los miembros de Lane Electric Cooperative (LEC) que se están atrasando a pagar su factura de LEC, hasta $250.\\n\\nActualización de COVID: solo con cita previa."}}, "HoursOfOperation": {"Value": {"en": "Monday to Thursday, 7:30 a.m. to 5:30 p.m.", "es": "Lunes a viernes de 7:30 a.m. a 5:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-08-11T17:07:00.387920'),
    (152, N'Laundry Unicorns - Eugene Mennonite Church', N'Individuals who live on the street may get their clothes laundered and dried for free. Currently picking up at scheduled camps for same day service. Call to see if we have an opening.', N'https://www.eugenemennonite.com/', N'peaceofeugene@gmail.com', N'Mondays, Wednesdays at 9 a.m. for pick ups', 1, N'{"Name": {"Value": {"en": "Laundry Unicorns - Eugene Mennonite Church"}}, "Description": {"Value": {"en": "Individuals who live on the street may get their clothes laundered and dried for free. Currently picking up at scheduled camps for same day service. Call to see if we have an opening.", "es": "Las personas que viven en la calle pueden lavar y secar la ropa de forma gratuita. Actualmente recogiendo en campamentos programados para servicio el mismo día. Llame para ver si tenemos una vacante."}}, "HoursOfOperation": {"Value": {"en": "Mondays, Wednesdays at 9 a.m. for pick ups", "es": "Lunes, miércoles a las 9 a.m. para recogidas"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (153, N'Laurel Hill Center - Employment Services', N'Job search support provided to those with psychiatric disabilities. Intake required.', N'http://www.laurel.org/', N'info@laurel.org', N'Intake Hours: Monday-Friday 8am-5pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-08-12T17:24:01.493036'),
    (154, N'Laurel Hill Center - Psychiatric Rehabilitation Services', N'Adult psychiatric rehabilitation center with housing, employment, outreach and wellness programs. Must have Oregon Health Plan.', N'http://www.laurel.org/', N'info@laurel.org', N'Monday to Friday, 8 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "Laurel Hill Center - Psychiatric Rehabilitation Services"}}, "Description": {"Value": {"en": "Adult psychiatric rehabilitation center with housing, employment, outreach and wellness programs. Must have Oregon Health Plan.", "es": "Centro de rehabilitación psiquiátrica para adultos con programas de vivienda, empleo, alcance y bienestar. Debe tener Oregon Health Plan."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 5 p.m.", "es": "Lunes a viernes de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (156, N'LGBTQ Youth Group', N'Call to inquire about appointments and current services. Group meetings and drop-ins might be suspended.', N'https://www.eugene-or.gov/2492/Amazon-Community-Center', N'', N'Call for hours', 1, N'{"Name": {"Value": {"en": "LGBTQ Youth Group"}}, "Description": {"Value": {"en": "Call to inquire about appointments and current services. Group meetings and drop-ins might be suspended.", "es": "Las reuniones de grupo y las visitas sin cita se suspenden hasta enero. Llame para solicitar información sobre citas y servicios actuales."}}, "HoursOfOperation": {"Value": {"en": "Call for hours", "es": "Viernes de 4 a 6 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (157, N'Lines for Life - Alcohol & Drug Helpline', N'For individuals and family members seeking crisis intervention, treatment referral, and chemical-dependency information. Call now, all hours. Or text “RecoveryNow” to 839863 (8 a.m. to 11 p.m.).', N'https://www.linesforlife.org/get-help-now/', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Lines for Life - Alcohol & Drug Helpline"}}, "Description": {"Value": {"en": "For individuals and family members seeking crisis intervention, treatment referral, and chemical-dependency information. Call now, all hours. Or text “RecoveryNow” to 839863 (8 a.m. to 11 p.m.).", "es": "Para individuos y familiares que buscan intervención en crisis, derivación de tratamiento e información sobre dependencia química. Llame ahora, a todas horas. O envíe un mensaje de texto con la palabra "RecoveryNow" al 839863 (de 8 a.m. a 11 p.m.)."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (158, N'Lines for Life - Military Crisis Line', N'Free, confidential support to service members, veterans and their families. Answered by veterans and others trained in military culture, our crisis lines offer compassionate, non-judgmental support and, where appropriate, connect people with the referrals, resources, or treatment they need through tough times.', N'https://www.linesforlife.org/mhl/', N'', N'24/7', 1, N'{"Name": {"Value": {"en": "Lines for Life - Military Crisis Line"}}, "Description": {"Value": {"en": "Free, confidential support to service members, veterans and their families. Answered by veterans and others trained in military culture, our crisis lines offer compassionate, non-judgmental support and, where appropriate, connect people with the referrals, resources, or treatment they need through tough times.", "es": ""}}, "HoursOfOperation": {"Value": {"en": "24/7", "es": "24/7"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (159, N'Lines for Life - Racial Equity Support', N'The Racial Equity Support Line is a service led and staffed by people with lived experience of racism. We offer support to those who are feeling the emotional impacts of racist violence and microaggressions, as well as the emotional impacts of immigration struggles and other cross-cultural issues.', N'https://www.linesforlife.org/racial-equity-support-line/', N'', N'Monday to Friday, 10 a.m. to 7 p.m.', 1, N'{"Name": {"Value": {"en": "Lines for Life - Racial Equity Support"}}, "Description": {"Value": {"en": "The Racial Equity Support Line is a service led and staffed by people with lived experience of racism. We offer support to those who are feeling the emotional impacts of racist violence and microaggressions, as well as the emotional impacts of immigration struggles and other cross-cultural issues.", "es": ""}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 10 a.m. to 7 p.m.", "es": "Lunes a viernes de 10 a.m. a 7 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (160, N'Lions Clubs International - State of Oregon', N'Can provide financial assistance for children and adults who need visual aids, hearing aids, eye or ear surgery. Phone referrals only, and services available only to qualifying applicants.', N'http://www.md36lionsclubs.org/', N'INFO@MD36LIONSCLUBS.ORG', N'Monday to Friday, 8 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "Lions Clubs International - State of Oregon"}}, "Description": {"Value": {"en": "Can provide financial assistance for children and adults who need visual aids, hearing aids, eye or ear surgery. Phone referrals only, and services available only to qualifying applicants.", "es": "El Club de Leones es un club de servicio que ofrece asistencia financiera a niños y adultos que necesitan ayudas visuales, audífonos, cirugía de ojos y oídos. Solo referencias telefónicas y servicios disponibles solo para solicitantes que califiquen."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 5 p.m.", "es": "Lunes a viernes de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (161, N'Looking Glass - New Roads Program', N'One-hour appointments available to those not in the overnight shelter Monday to Friday 10 a.m. to 3 p.m. for food, clothing and showers. Drop-in hours are Monday to Friday, 5 p.m. to 7 p.m.\\n\\nOvernight shelter for youth 12-21 only. Meals provided for overnight guests.\\n\\nCOVID Update:  screening at the door.', N'https://www.lookingglass.us/new-roads', N'', N'Monday through Friday, 10 a.m. to 3 p.m. and 5 to 7 p.m.', 1, N'{"Name": {"Value": {"en": "Looking Glass - New Roads Program"}}, "Description": {"Value": {"en": "One-hour appointments available to those not in the overnight shelter Monday to Friday 10 a.m. to 3 p.m. for food, clothing and showers. Drop-in hours are Monday to Friday, 5 p.m. to 7 p.m.\\n\\nOvernight shelter for youth 12-21 only. Meals provided for overnight guests.\\n\\nCOVID Update: screening at the door.", "es": "Proyección de COVID en la puerta.\\n\\nCitas de una hora disponibles para quienes no están en el refugio nocturno de lunes a viernes de 10 a.m. a 3 p.m. para comida, ropa y duchas. El horario de atención es de lunes a viernes a las 5 p.m. a las 7 p.m.\\n\\nRefugio nocturno solo para jóvenes de 12 a 21 años. Comidas ofrecidas para los huéspedes durante la noche."}}, "HoursOfOperation": {"Value": {"en": "Monday through Friday, 10 a.m. to 3 p.m. and 5 to 7 p.m.", "es": "Lunes a viernes de 8:30 a.m. a 3:30 p.m. y 5 a 7 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (162, N'Looking Glass - Station #7', N'Provides crisis intervention services and temporary emergency shelter for runaway and homeless youth ages 11-17.', N'https://www.lookingglass.us/station-7', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Looking Glass - Station #7"}}, "Description": {"Value": {"en": "Provides crisis intervention services and temporary emergency shelter for runaway and homeless youth ages 11-17.", "es": "Ofrece servicios de intervención en caso de crisis y refugio temporal de emergencia para jóvenes sin hogar y sin hogar de 11 a 17 años."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre abierta"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (163, N'Looking Glass Community Services', N'Outpatient mental health and substance abuse treatment. Individual, family, and group therapy for children, adolescents, adults, and their families.', N'https://www.lookingglass.us/', N'', N'Monday to Thursday 8 a.m. to 6 p.m.; Friday 8 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "Looking Glass Community Services"}}, "Description": {"Value": {"en": "Outpatient mental health and substance abuse treatment. Individual, family, and group therapy for children, adolescents, adults, and their families.", "es": "Tratamiento ambulatorio de salud mental y abuso de sustancias. Terapia individual, familiar y grupal para niños, adolescentes, adultos y sus familias."}}, "HoursOfOperation": {"Value": {"en": "Monday to Thursday 8 a.m. to 6 p.m.; Friday 8 a.m. to 5 p.m.", "es": "Lunes a jueves, 8 a.m. a 6 p.m.; viernes de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (164, N'Looking Glass Crisis Response Line', N'24-hour crisis prevention helpline for families with children or runaways ages 17 and under.', N'https://www.lookingglass.us/', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Looking Glass Crisis Response Line"}}, "Description": {"Value": {"en": "24-hour crisis prevention helpline for families with children or runaways ages 17 and under.", "es": "Línea de ayuda para la prevención de crisis las 24 horas para familias con niños o fugitivos menores de 17 años."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (165, N'Love for Lane County', N'The Call Center will listen to your needs and try to find a service that will provide assistance. (Unable to help in crisis or housing situations.) Distribute donations including furniture for newly housed individuals – medical rides for those who cannot drive.  
INSERT INTO dbo.[Provider] ([ProviderId], [Name], [Description], [WebAddress], [EmailAddress], [HoursOfOperation], [IsActive], [l10N], [CreatedBy], [CreatedOn], [ModifiedBy], [ModifiedOn]) VALUES
    (222, N'Oregon Law Help', N'Website that provides information on a variety of legal issues, including family, abuse, seniors, employment, tenant issues, disability, and farm workers. Many languages available.', N'https://oregonlawhelp.org/', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Oregon Law Help"}}, "Description": {"Value": {"en": "Website that provides information on a variety of legal issues, including family, abuse, seniors, employment, tenant issues, disability, and farm workers. Many languages available.", "es": "Sitio web que ofrece información sobre una variedad de temas legales, incluidos la familia, el abuso, las personas mayores, el empleo, los inquilinos, la discapacidad y los trabajadores agrícolas. Numerosos idiomas disponibles."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (223, N'Oregon Lifeline', N'Offers free service or discounted service. This is a federal and state government program that reduces the monthly cost of phone or broadband service for qualifying low-income Oregon households.  ', N'https://www.oregon.gov/puc/Pages/Oregon-Lifeline.aspx', N'puc.rspf@puc.oregon.gov', N'9 a.m. to 4 p.m. Monday through Friday', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T22:07:11.884663'),
    (224, N'Oregon Low Income Home Energy Assistance Program', N'Designed to help low income households with home heating and cooling costs. To qualify, apply online or call.', N'https://lanecounty.org/cms/One.aspx?portalId=3585881&pageId=9773412', N'', N'Monday to Friday, 8 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "Oregon Low Income Home Energy Assistance Program"}}, "Description": {"Value": {"en": "Designed to help low income households with home heating and cooling costs. To qualify, apply online or call.", "es": "Diseñado para ayudar a los hogares de bajos ingresos con los costos de calefacción y refrigeración del hogar. Para calificar, aplique en línea o llame."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 5 p.m.", "es": "Lunes a viernes de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (225, N'Oregon Relay ', N'Free 24-hour statewide service for deaf, hard of hearing, deaf-blind, speech disabled, to place and receive calls.', N'https://www.oregonrelay.com', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Oregon Relay"}}, "Description": {"Value": {"en": "Free 24-hour statewide service for deaf, hard of hearing, deaf-blind, speech disabled, to place and receive calls.", "es": "Servicio gratuito de 24 horas en todo el estado para personas sordas, con problemas de audición, sordo-ciegos, discapacitados del habla, para realizar y recibir llamadas."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (226, N'Oregon State Bar Referral and Information Services', N'Refers clients to attorneys by area of law for an office consultation in a client''s geographical area. Attorneys agree to charge no more than $35 for the initial consultation.', N'https://www.osbar.org/public/ris/', N'', N'Monday to Friday, 8 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "Oregon State Bar Referral and Information Services"}}, "Description": {"Value": {"en": "Refers clients to attorneys by area of law for an office consultation in a client''s geographical area. Attorneys agree to charge no more than $35 for the initial consultation.", "es": "Refiere a los clientes a abogados por área de derecho para una consulta de oficina en el área geográfica de un cliente. Los abogados acuerdan cobrar no más de $35 por la consulta inicial."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 5 p.m.", "es": "Lunes a viernes de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (227, N'Oregon Vital Records', N'Obtain birth and death certificates for all of Oregon. Look at the website before you try to order a certificate for the necessary information.', N'https://www.oregon.gov/oha/PH/BIRTHDEATHCERTIFICATES/GETVITALRECORDS/Pages/index.aspx ', N'', N'Phone: 24/7 , 7 days a week', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T22:09:05.426038'),
    (228, N'Our Redeemer Lutheran Church Food Pantry', N'Food pantry is open every second and fourth Saturday of each month, 10 a.m. to noon. ', N'http://www.ourredeemereugene.org/', N'orlc@riousa.com', N'Second and fourth Saturday, 9:30am -12:00pm ', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T22:10:24.903022'),
    (230, N'Parenting Now', N'Provides free parenting education and support to families with young children. Free car seats by arrangement.', N'https://parentingnow.org/', N'', N'Monday to Thursday, 9 a.m. to 4 p.m.', 1, N'{"Name": {"Value": {"en": "Parenting Now"}}, "Description": {"Value": {"en": "Provides free parenting education and support to families with young children. Free car seats by arrangement.", "es": "Se ofrece educación y apoyo gratuitos para padres a familias con niños pequeños. Asiento infantil gratis con cita previa."}}, "HoursOfOperation": {"Value": {"en": "Monday to Thursday, 9 a.m. to 4 p.m.", "es": "Lunes a jueves de 9 a.m. a 4 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (231, N'Peace Harbor Hospital - Home Care Services', N'Individualized in-home care is available for patients of all ages, from newborns to seniors. Hospice services also provided. Call for eligibility requirements and details about service. Also services Deadwood, Yachats, and Westlake.', N'https://www.peacehealth.org/', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Peace Harbor Hospital - Home Care Services"}}, "Description": {"Value": {"en": "Individualized in-home care is available for patients of all ages, from newborns to seniors. Hospice services also provided. Call for eligibility requirements and details about service. Also services Deadwood, Yachats, and Westlake.", "es": "La atención personalizada a domicilio está disponible para pacientes de todas las edades, desde recién nacidos hasta personas mayores. También se ofrece servicios de hospicio. Llame para conocer los requisitos de elegibilidad y los detalles sobre el servicio. También presta servicios a Deadwood, Yachats y Westlake."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre abierta"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (232, N'Peacehealth Medical Group - Cottage Grove Community Hospital and Clinics', N'Hospital with a 24-hour emergency room.', N'https://www.peacehealth.org/hospitals/peacehealth-cottage-grove-community-medical-center', N'', N'All hours, every day', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T22:13:03.090982'),
    (235, N'PeaceHealth Medical Group - Urgent Care Center / West 11th', N'Same day care for less than an emergency room. Accepts OHP.', N'https://www.peacehealth.org/', N'', N'Every day, 8 a.m. to 7 p.m.', 1, N'{"Name": {"Value": {"en": "PeaceHealth Medical Group - Urgent Care Center / West 11th"}}, "Description": {"Value": {"en": "Same day care for less than an emergency room. Accepts OHP.", "es": "Atención el mismo día por menos de una sala de emergencias. Acepta OHP."}}, "HoursOfOperation": {"Value": {"en": "Every day, 8 a.m. to 7 p.m.", "es": "Todos los días de 8 a.m. a 7 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (236, N'PeaceHealth Medical Group – Urgent Care Center, University District', N'Same day care for less than an emergency room. Accepts OHP.', N'https://www.peacehealth.org/ https://www.peacehealth.org/locations/eugene/urgent-care-peacehealth-university-district', N'', N'Everyday, 8am – 8pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T22:16:43.607223'),
    (237, N'PeaceHealth Sacred Heart Riverbend', N'Full hospital with 24-hour emergency room.', N'https://www.peacehealth.org/hospitals/peacehealth-sacred-heart-medical-center-riverbend', N'', N'All hours, every day', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T22:17:34.327871'),
    (239, N'PenFed Foundation', N'Emergency financial assistance program offers financial assistance for wounded, ill, and injured post 9-11 combat veterans who are experiencing an unexpected short term (one to two months) financial setback. Apply on website.', N'https://penfedfoundation.org/', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "PenFed Foundation"}}, "Description": {"Value": {"en": "Emergency financial assistance program offers financial assistance for wounded, ill, and injured post 9-11 combat veterans who are experiencing an unexpected short term (one to two months) financial setback. Apply on website.", "es": "El programa de asistencia financiera de emergencia ofrece asistencia financiera para los veteranos de combate heridos, enfermos y lesionados después del 11 de septiembre que están experimentando un revés financiero inesperado a corto plazo (1 a 2 meses). Aplicar en el sitio web."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (240, N'Pink Fund', N'Provides financial assistance for those who have been diagnosed with breast cancer and are undergoing active treatment. Qualified candidates may receive cost-of-living assistance for bills during treatment and recovery. Inquire about grants by email.', N'info@thepinkfund.org', N'grants@thepinkfund.org', N'Monday to Friday, 9 a.m. to 5 p.m.', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'PatriciaC', '2024-09-21T22:19:02.460066'),
    (241, N'Planned Parenthood of Southwestern OR - Eugene', N'A private family-planning agency providing pregnancy tests, birth control, STI screening and treatment, HIV testing, pregnancy testing, men''s and women''s health care services, reproductive health counseling, and education. Menstrual care packets and condoms are available. Accepts Oregon Health Plan.', N'https://www.plannedparenthood.org/health-center/oregon/eugene/97403/eugene-springfield-health-center-4075-91380', N'', N'Monday - Wednesday 9:30 a.m. to 6 p.m. Thursday 10:30 a.m. to 6 p.m. Friday 8am-4pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-17T20:24:28.240148'),
    (242, N'Planned Parenthood West Eugene Health Center', N'Services provided include: Pregnancy tests, birth control, STI and HIV testing, pregnancy testing, abortion referral, both women’s and men’s health care, reproductive health counseling and education. Menstrual care packets and condoms are available. Accepts Oregon Health Plan.', N'https://www.plannedparenthood.org/health-center/oregon/eugene/97402/west-eugene-health-center-3069-91380', N'', N'Monday, Tuesday, Wednesday, Friday 9:30 a.m. to 6 p.m. and Thurday 10:30 a.m. to 6 p.m. Monday - Wednesday 9:30 a.m. to 6 p.m. Thursday 10:30 a.m. to 6 p.m. Friday 9:30am-6pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-17T20:27:11.800329'),
    (243, N'Pro-Bone-O', N'Provides free clinics for the pets of homeless individuals. Vaccinations, flea and tick prevention, treatment of minor ailments, spay/neuter vouchers, worming, food and treats. The clinics are  on the second and fourth Sundays from February to October and on the second Sunday, November through January. Clinics are held at the Eugene Mission warehouse at 1509 W 1st Ave, Eugene, OR - (across the street from the main Eugene Mission offices and housing).Patients are seen on a first-come, first-serve basis, with gates opening at 8:45 am. To respect volunteer time, the last patients will be admitted into the clinic at 12pm. ', N'http://proboneo.org/', N'', N'See description for times', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-17T20:33:42.849348'),
    (244, N'Produce Plus - Bethel Farm ', N'During the school year (September to June), the program provides fresh fruits and vegetables to households in Lane County living at or below 200% of the Federal Poverty Level, with no program enrollment.', N'https://foodforlanecounty.org/get-help/trillium-produce-plus/', N'', N'Wednesdays from 10:00 am to 12:00 pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-17T22:56:42.323539'),
    (245, N'Produce Plus - Bethel’s Cascade Middle School ', N'Produce Plus program provides brings fresh fruits and vegetables to households in Lane County living at or below 200% of the Federal Poverty Level, with no program enrollment.', N'http://blogs.bethel.k12.or.us/thebethelfarm/produce-plus-free-market/', N'', N'Tuesdays noon to 4 p.m. when the school is open', 1, N'{"Name": {"Value": {"en": "Produce Plus - Bethel’s Cascade Middle School"}}, "Description": {"Value": {"en": "Produce Plus program provides brings fresh fruits and vegetables to households in Lane County living at or below 200% of the Federal Poverty Level, with no program enrollment.", "es": "El programa Produce Plus ofrece frutas y verduras frescas a los hogares en el condado de Lane que viven en o por debajo del 200% del nivel federal de pobreza, sin inscripción en el programa."}}, "HoursOfOperation": {"Value": {"en": "Tuesdays noon to 4 p.m. when the school is open", "es": "Martes mediodía a 4 p.m. cuando la escuela esta abierta"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (246, N'Produce Plus - Unitarian Universalist Church ', N'Program provides fresh fruits and vegetables to households in Lane County living at or below 300% of the Federal Poverty Level, with no program enrollment.', N'https://uueugene.org/economic-justice/', N'', N'First and third Tuesday, 2 to 4 p.m.  ', 1, N'{"Name": {"Value": {"en": "Produce Plus - Unitarian Universalist Church"}}, "Description": {"Value": {"en": "Program provides fresh fruits and vegetables to households in Lane County living at or below 200% of the Federal Poverty Level, with no program enrollment.", "es": "El programa Produce Plus ofrece frutas y verduras frescas a los hogares en el condado de Lane que viven en o por debajo del 200% del nivel federal de pobreza, sin inscripción en el programa."}}, "HoursOfOperation": {"Value": {"en": "First and third Tuesday, 3 to 6 p.m.", "es": "Primer y tercer martes de 3 a 6 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-17T23:01:27.678775'),
    (247, N'Project Safe Place', N'Find a Safe Place location by entering an address or zip code in their website or by texting. Within seconds, you will receive a message with the closest Safe Place site and phone number for the local youth agency. You will also have the option to text interactively with a professional for more help. \\n\\nThis national program provides youth with safe places to seek help. Youth ages 11-17 can access any of the 68 Safe Place sites across Lane County identified by the yellow and black diamond-shaped signs. Staff at each site are trained to assist the youth in contacting Station 7. Participating businesses are identified by highly visible yellow and black diamond-shaped signs.', N'https://www.nationalsafeplace.org/find-a-safe-place', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Project Safe Place"}}, "Description": {"Value": {"en": "Find a Safe Place location by entering an address or zip code in their website or by texting. Within seconds, you will receive a message with the closest Safe Place site and phone number for the local youth agency. You will also have the option to text interactively with a professional for more help. \\n\\nThis national program provides youth with safe places to seek help. Youth ages 11-17 can access any of the 68 Safe Place sites across Lane County identified by the yellow and black diamond-shaped signs. Staff at each site are trained to assist the youth in contacting Station 7. Participating businesses are identified by highly visible yellow and black diamond-shaped signs.", "es": "Encuentre una ubicación de lugar seguro ingresando una dirección o código postal en su sitio web o enviando un mensaje de texto. En segundos, recibirá un mensaje con el sitio Safe Place más cercano y el número de teléfono de la agencia juvenil local. También tendrá la opción de enviar mensajes de texto de forma interactiva con un profesional para obtener más ayuda.\\n\\nEste programa nacional ofrece a los jóvenes lugares seguros para buscar ayuda. Los jóvenes de 11 a 17 años pueden acceder a cualquiera de los 68 sitios de Safe Place en el condado de Lane identificados por los letreros amarillos y negros en forma de diamante. El personal de cada sitio está capacitado para ayudar a los jóvenes a comunicarse con la Estación 7. Los negocios participantes se identifican mediante letreros muy visibles en forma de diamante amarillo y negro."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (248, N'Public Benefits Hotline', N'Provides assistance for those who are having trouble with government benefits, such as social security, food stamps, Oregon Health Plan and others.', N'https://oregonlawhelp.org/resource/public-benefits-information-hotline', N'', N'Monday 1 pm - 4 pm, Tuesday 9:30 am - 12:30 pm, Wednesday 9:30 am - 12:30 pm', 1, N'{"Name": {"Value": {"en": "Public Benefits Hotline"}}, "Description": {"Value": {"en": "Provides assistance for those who are having trouble with government benefits, such as social security, food stamps, Oregon Health Plan and others.", "es": "Ofrece asistencia a quienes tienen problemas con los beneficios del gobierno, como el seguro social, cupones de alimentos, el Plan de Salud de Oregon y otros."}}, "HoursOfOperation": {"Value": {"en": "Monday to Thursday, 9:30 a.m. to 12:30 p.m., 1 to 4 p.m.", "es": "Lunes a jueves de 9:30 a.m. a 12:30 p.m., 1 a 4 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-17T23:07:38.989011'),
    (249, N'RecordSponge', N'Are you looking to clear your record? The Public Defender Services of Lane County can provide analysis and help you file for expungement. The majority of court fees are subject to waiver for income-qualified individuals who complete the waiver form. Please contact: http://www.lanepds.org', N'https://recordsponge.com/', N'', N'Monday to Friday, 8 a.m. to 12 p.m. and 1 p.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "RecordSponge"}}, "Description": {"Value": {"en": "Are you looking to clear your record? The Public Defender Services of Lane County can provide analysis and help you file for expungement. The majority of court fees are subject to waiver for income-qualified individuals who complete the waiver form. Please contact: http://www.lanepds.org", "es": "¿Está buscando limpiar su registro? Los Servicios de Defensores Públicos del Condado de Lane pueden proporcionar análisis y ayudarlo a solicitar la eliminación. La mayoría de las tasas judiciales están sujetas a exenciones para las personas con ingresos calificados que completen el formulario de exención. Póngase en contacto con: http://www.lanepds.org"}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 12 p.m. and 1 p.m. to 5 p.m.", "es": "Lunes a viernes de 8 a.m. a 12 p.m. y 1 p.m. a las 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
