    (256, N'SASS - Sexual Assault Support Services', N'Counseling and support services for those who are sexually assaulted (present or past). Services free of charge. Crisis line is offered 24/7. Drop-ins for in-person services should call ahead at the business line.', N'http://sass-lane.org/', N'', N'Tuesday, Wednesday, Thursday 9 a.m. to 4 p.m., drop-in center hours', 1, N'{"Name": {"Value": {"en": "SASS - Sexual Assault Support Services"}}, "Description": {"Value": {"en": "Counseling and support services for those who are sexually assaulted (present or past). Services free of charge.\\n\\nCOVID Update: In-person services are on hold, support groups are offered online. Spanish spoken.", "es": "Servicios de asesoramiento y apoyo para quienes son agredidos sexualmente (presentes o pasados). Servicios sin cargo.\\n\\nActualización de COVID: los servicios en persona están en espera, los grupos de apoyo se ofrecen en línea. Se habla español."}}, "HoursOfOperation": {"Value": {"en": "Tuesday, Wednesday, Thursday 9 a.m. to 4 p.m., drop-in center hours", "es": "Martes, miércoles y jueves de 9 a.m. a 4 p.m., horario del centro sin cita previa"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-18T02:20:40.296138'),
