    (258, N'School Health Centers, Eugene School District', N'Health clinics for students and siblings ages 0 - 18 during the school year, sliding-scale costs. Mental health counselors on site Monday, Tuesday, Thursday, Friday from 8 am to 4 pm. Nurse onsite at Churchill, Monday and Thursday.', N'https://4j.lane.edu/healthcare-providers', N'', N'Located in the description', 1, N'{"Name": {"Value": {"en": "School Health Centers, Eugene School District"}}, "Description": {"Value": {"en": "Health clinics for students and siblings ages 0 to 18 during school year; sliding-scale costs. Mental health counselors on site Monday, Tuesday, Thursday, Friday from 8 a.m. to 4 p.m. Nurse on site at Churchill, Monday and Thursday.", "es": "Clínicas de salud para estudiantes y hermanos de 0 a 18 años durante el año escolar, costos de escala móvil. Consejeros de salud mental en ambos sitios los lunes, martes, jueves y viernes de 8 a.m. a 4 p.m. Enfermera en el lugar en Churchill, los lunes y jueves, y en North Eugene, los martes y viernes."}}, "HoursOfOperation": {"Value": {"en": "During the school year, Monday to Friday, 8 a.m. to 4:30 p.m.", "es": "Durante el año escolar, de lunes a viernes de 8 a.m. a 4:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-18T02:34:06.769631'),
