    (272, N'Siuslaw Outreach Services', N'Provides assistance with emergency shelter, housing, rent and utility assistance, prescription assistance, homeless prevention, shower, laundry, transportation vouchers, special veterans program, and domestic violence / sexual abuse advocacy.', N'https://florencesos.org/services.html', N'', N'Monday to Thursday, 10 a.m. to 3:30 p.m., Friday by appointment', 1, N'{"Name": {"Value": {"en": "Siuslaw Outreach Services"}}, "Description": {"Value": {"en": "Provides assistance with emergency shelter, housing, rent and utility assistance, prescription assistance, homeless prevention, shower, laundry, transportation vouchers, special veterans program, and domestic violence / sexual abuse advocacy.", "es": "Ofrece asistencia con: refugio de emergencia, vivienda, asistencia con el alquiler y los servicios públicos, asistencia con medicamentos recetados, prevención para personas sin hogar, ducha, lavandería, vales de transporte, programa especial para veteranos, defensa de la violencia doméstica / abuso sexual."}}, "HoursOfOperation": {"Value": {"en": "Monday to Thursday, 10 a.m. to 3:30 p.m., Friday by appointment", "es": "Lunes a jueves, 10 a.m. a 3:30 p.m., viernes con cita previa"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
