    (278, N'South Lane Wheels', N'South Lane Wheels is a public transportation system that connects people with where they want to go in South Lane County including Cottage Grove, Creswell, Dorena, Culp Creek, Saginaw, London, and Lorane. ', N'http://southlanetransit.com/', N'', N'Monday to Friday, 8:00 a.m. to 5:00 p.m. ', 1, N'{"Name": {"Value": {"en": "South Lane Wheels"}}, "Description": {"Value": {"en": "Accessible public transportation in the Cottage Grove and Creswell area with service to Eugene and Springfield destinations. Information and referral also provided. LTD Connector, a door-to-door transportation service to any location in the Cottage Grove area, offered from 8 a.m. to 5 p.m. Monday to Friday.", "es": "Transporte público accesible en el área de Cottage Grove y Creswell con servicio a los destinos de Eugene y Springfield. También se ofrece información y derivación. LTD Connector, un servicio de transporte puerta a puerta a cualquier lugar en el área de Cottage Grove, que se ofrece de 8 a.m. a 5 p.m. de lunes a viernes."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8:00 a.m. to 5:00 p.m.", "es": "Lunes a viernes, 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-29T02:29:54.920093'),
    (279, N'Sponsors, Inc. - Re-Entry Resource Center', N'Services for those on probation or parole. Transitional housing for men and women. Information, resources and referrals to find employment. Access to computers.', N'https://sponsorsinc.org/reentry-resource-center/', N'', N'Monday to Friday, 8 a.m. to 4:30 p.m.', 1, N'{"Name": {"Value": {"en": "Sponsors, Inc. - Re-Entry Resource Center"}}, "Description": {"Value": {"en": "Services for those on probation or parole. Transitional housing for men and women. Information, resources and referrals to find employment.\\n\\nCOVID Update: No drop ins during pandemic. Please call for assistance.", "es": "Servicios para personas en libertad condicional o bajo palabra. Vivienda de transición para hombres y mujeres. Información, recursos y referencias para encontrar empleo.\\n\\nActualización de COVID: no hay visitas durante la pandemia. Por favor llame para obtener ayuda."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 4:30 p.m.", "es": "Lunes a viernes de 8 a.m. a 4:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-29T19:17:49.004302'),
    (280, N'Sponsors, Inc. - Re-Entry Resource Center – Women''s Assistance Program', N'Women’s assistance program to re-enter life after incarceration. Services for those on probation or parole. Transitional housing for men and women. Information, resources and referrals to find employment.\\n\\nCOVID Update: No drop-ins during pandemic. Please call for assistance.', N'https://sponsorsinc.org/reentry-resource-center/', N'', N'Monday to Friday, 8 a.m. to 4:30 p.m.', 1, N'{"Name": {"Value": {"en": "Sponsors, Inc. - Re-Entry Resource Center – Women''s Assistance Program"}}, "Description": {"Value": {"en": "Women’s assistance program to re-enter life after incarceration. Services for those on probation or parole. Transitional housing for men and women. Information, resources and referrals to find employment.\\n\\nCOVID Update: No drop-ins during pandemic. Please call for assistance.", "es": "Programa de asistencia a la mujer para reingresar a la vida después del encarcelamiento. Servicios para personas en libertad condicional o bajo palabra. Vivienda de transición para hombres y mujeres. Información, recursos y referencias para encontrar empleo.\\n\\nActualización de COVID: no hay visitas durante la pandemia. Por favor llame para obtener ayuda."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 4:30 p.m.", "es": "Lunes a viernes de 8 a.m. a 4:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (281, N'SPOT (Stop Pet Overpopulation Today)', N'Gives vouchers to help cover costs for spaying or neutering dogs of low-income individuals. Co-pays are based on level of need and all breeds are eligible. Preferred contact by website, please fill out application. Phone calls are returned Monday-Friday generally within 48 hours.', N'https://www.spotspayneuter.org/apply/', N'admin@spotspayneuter.org', N'By appointment only', 1, N'{"Name": {"Value": {"en": "SPOT (Stop Pet Overpopulation Today)"}}, "Description": {"Value": {"en": "Gives vouchers to help cover costs for spaying or neutering dogs of low-income individuals. Co-pays are based on level of need and all breeds are eligible. Preferred contact by website, please fill out application. Phone calls are returned Monday-Friday generally within 48 hours.", "es": "Ofrece vales para ayudar a cubrir los costos de esterilización o castración de perros de personas de bajos ingresos. Los copagos se basan en el nivel de necesidad y todas las razas son elegibles. Contacto preferido por sitio web."}}, "HoursOfOperation": {"Value": {"en": "", "es": "Proporcione lo solicitado en un mensaje telefónico para agilizar su proceso. Devuelven las llamadas de lunes a viernes, en un plazo de 48 horas, pero generalmente antes."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-29T19:26:07.238421'),
    (282, N'Springfield Adventist Community Center', N'Food pantry available on the first and third Tuesday 10 a.m. to 1 p.m. and the second and fourth Tuesday from 4 to 7 p.m. If you have a food or clothing need outside those hours, give their office a call.', N'https://springfieldor.adventistchurch.org/ministries/community-services', N'', N'First and third Tuesday 10 to 1 p.m.; Second and fourth Tuesday 4 p.m. to 7 p.m.', 1, N'{"Name": {"Value": {"en": "Springfield Adventist Community Center"}}, "Description": {"Value": {"en": "Food pantry available on the first and third Tuesday 10 a.m. to 1 p.m. and the second and fourth Tuesday from 4 to 7 p.m. Clothing available by appointment only; please call the office on Thursday or Friday.", "es": "Despensa de alimentos disponible el primer y tercer martes de 10 a.m. a 1 p.m. y el segundo y cuarto martes de 16 a 19 h. Ropa disponible solo con cita previa, llame a la oficina el jueves o viernes."}}, "HoursOfOperation": {"Value": {"en": "First and third Tuesday 10 to 1 p.m.; Second and fourth Tuesday 4 p.m. to 7 p.m.", "es": "Primer y tercer martes de 10 a 1 p.m .; Segundo y cuarto martes 4 p.m. a las 7 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-29T19:29:54.190624'),
