    (287, N'St. Vincent de Paul - Eugene Service Station', N'Provides day shelter, bathrooms, meals, laundry services, showers, telephones, mail services, and Dusk to Dawn shelter. Also provides vouchers for St. Vincent’s thrift stores, which can be used for clothes, bedding, and other items.', N'https://www.svdp.us/services/emergency-services/eugene-service-station/', N'', N'Every day, 8 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "St. Vincent de Paul - Eugene Service Station"}}, "Description": {"Value": {"en": "Provides day shelter, bathrooms, meals, laundry services, showers, telephones, mail services, and Dusk to Dawn shelter. Also provides vouchers for St. Vincent’s thrift stores, which can be used for clothes, bedding, and other items.", "es": "La estación de servicio Eugene ofrece refugio diurno, baños, comidas, servicios de lavandería, duchas, teléfonos, servicios de correo y refugio Dusk to Dawn. También se ofrece vales para las tiendas de segunda mano de St. Vincent, que se pueden utilizar para comprar ropa, ropa de cama y otros artículos."}}, "HoursOfOperation": {"Value": {"en": "Every day, 8 a.m. to 5 p.m.", "es": "Todos los días de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-29T22:49:56.454399'),
    (288, N'St. Vincent de Paul Social Services', N'Social Services provides one-time rental assistance, a food pantry, clothing, vouchers for household goods and furniture, propane, prescription assistance, and Second Chance Renters Rehabilitation. By appointment only.', N'https://www.svdp.us/get-help/', N'', N'By appointment only, call to schedule. Monday, Tuesday, Wednesday & Friday from 9 am to 4 pm.', 1, N'{"Name": {"Value": {"en": "St. Vincent de Paul Social Services"}}, "Description": {"Value": {"en": "Currently closed.\\n\\nSocial Services provides one-time rental assistance, a food pantry, clothing, vouchers for household goods and furniture, propane, prescription assistance, and Second Chance Renters Rehabilitation.", "es": "Actualmente cerrado.\\n\\nLos Servicios Sociales ofrece asistencia de alquiler por única vez, una despensa de alimentos, ropa, vales para artículos y muebles para el hogar, propano, asistencia para recetas y rehabilitación de inquilinos de segunda oportunidad."}}, "HoursOfOperation": {"Value": {"en": "Currently closed", "es": "Actualmente cerrado"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-30T00:35:37.227694'),
