    (291, N'St. Vincent de Paul Support Services for Veteran Families', N'Housing assistance, eviction prevention, case management, referrals and assistance to other services and benefits. Aimed at helping homeless veterans and those at risk of homelessness with the resources needed to become or remain permanently housed.', N'https://www.svdp.us/services/supportive-housing/veterans-services/', N'', N'Monday to Friday, 8 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "St. Vincent de Paul Support Services for Veteran Families"}}, "Description": {"Value": {"en": "Housing assistance, eviction prevention, case management, referrals and assistance to other services and benefits. Aimed at helping homeless veterans and those at risk of homelessness with the resources needed to become or remain permanently housed.", "es": "Asistencia de vivienda, prevención de desalojos, administración de casos, referencias y asistencia a otros servicios y beneficios. Destinado a ayudar a los veteranos sin hogar y aquellos en riesgo de quedarse sin hogar con los recursos necesarios para tener o permanecer en una vivienda permanente."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 5 p.m.", "es": "Lunes a viernes de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-30T00:42:58.351092'),
