    (293, N'Summer Food Program by Food for Lane County', N'Meals available Monday to Friday for children 18 and under; from late June to late August. Variety of locations throughout Lane County, different every summer. Please call or check the website for schedule.', N'https://foodforlanecounty.org/get-help/', N'', N'Summers, Monday to Friday, 11:30 am to 12:30 pm', 1, N'{"Name": {"Value": {"en": "Summer Food Program by Food for Lane County"}}, "Description": {"Value": {"en": "Meals available Monday to Friday for children 18 and under; from late June to late August. Variety of locations throughout Lane County, different every summer. Please call or check the website for schedule.\\n\\nCOVID Update: Food to go provided", "es": "Comidas de lunes a viernes para menores de 18 años todos los veranos desde finales de junio hasta finales de agosto. Variedad de ubicaciones en todo el condado de Lane y es diferente cada verano. Por favor llame o visite el sitio web para conocer el horario."}}, "HoursOfOperation": {"Value": {"en": "Summers, Monday to Friday, 9 a.m. to 4 p.m.", "es": "Veranos, de lunes a viernes, de 9 a.m. a 4 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-30T00:48:33.726676'),
