    (303, N'Syringe Drop-Box - Washington-Jefferson Park', N'Place syringes in the container near skatepark. ', N'https://hivalliance.org/prevent/syringe-services/', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Syringe Drop-Box - Washington-Jefferson Park"}}, "Description": {"Value": {"en": "Place syringes in the container near skatepark. Address on HIV Alliance website may be in error.", "es": "Sitio de depósito de jeringas.\\n\\nAl consultar el sitio web de la HIV Alliance, disculpe la dirección que han incluido para el Washington-Jefferson Park, para todos los que estén familiarizados con Eugene, se verá mal y está apagado. La dirección incluida aquí, cerca del skatepark, es la indicada."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-30T18:33:27.153511'),
    (304, N'Syringe Drop-Box Sites', N'Syringe drop-box sites in Eugene/Springfield: HIV Alliance Main Office: 1195a City View St, White Bird Clinic: 341 E 12th Ave,  Buckley House Detox: 605 W 4th Ave, Springfield Library: 225 N 5th St, Springfield, Eugene Service Station on Hwy 99: 450 OR-99, Washington-Jefferson Park near the skatepark restrooms, Alton Baker Park: 100 Day Island Park (near the bathroom), Emergence: 1461 Oak St, Coburg Bike Path: near 76 Gas Station (near the corner of Coburg and MLK Jr. Blvd), For locations throughout Lane County for disposing your sharps disposal containers year-round, see the Prevention Lane website.', N'https://preventionlane.org/sharps-disposal-locations-in-lane-county', N'', N'See website for hours by location', 1, N'{"Name": {"Value": {"en": "Syringe Drop-Box Sites"}}, "Description": {"Value": {"en": "Syringe drop-box sites in Eugene/Springfield:\\n\\n HIV Alliance Main Office: 1195a City View St\\n White Bird Clinic: 341 E 12th Ave\\n Buckley House Detox: 605 W 4th Ave\\n Springfield Library: 225 N 5th St, Springfield\\n Eugene Service Station on Hwy 99: 450 OR-99\\n Washington-Jefferson Park near the skatepark restrooms\\n Alton Baker Park: 100 Day Island Park (near the bathroom)\\n Emergence: 1461 Oak St\\n Coburg Bike Path: near 76 Gas Station (near the corner of Coburg and MLK Jr. Blvd)\\n\\nFor locations throughout Lane County for disposing your sharps disposal containers year-round, see the Prevention Lane website.", "es": "Sitio de depósito de jeringas en Eugene / Springfield:\\n\\n Oficina principal de HIV Alliance: 1195a City View St.\\n Clínica White Bird: 341 E 12th Ave.\\n Desintoxicación de la casa Buckley: 605 W 4th Ave.\\n Biblioteca de Springfield: 225 N 5th St., Springfield\\n Estación de servicio Eugene en Hwy 99: 450 OR-99\\n Parque Washington-Jefferson cerca de los baños del skatepark\\n Alton Baker Park: 100 Day Island Park (cerca del baño)\\n Emergencia: 1461 Oak St.\\n Carril bici Coburg: cerca de la gasolinera 76 (cerca de la esquina de Coburg y MLK Jr. Blvd.)\\n\\nPara conocer las ubicaciones en todo el condado de Lane para desechar sus contenedores de eliminación de objetos punzantes durante todo el año, consulte el sitio web de Prevention Lane."}}, "HoursOfOperation": {"Value": {"en": "See website for hours by location", "es": "Consulte el sitio web para conocer los horarios por ubicación"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-30T18:42:09.637840'),
    (305, N'Riverview Center for Growth', N'24/7 Crisis Response Program providing support and help to teens, children, parents and families during times of crisis. Must call first.', N'https://riverviewgrowth.org', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "The Child Center Crisis Response Program"}}, "Description": {"Value": {"en": "24/7 Crisis Response Program providing support and help to teens, children, parents and families during times of crisis. Must call first.", "es": "Programa de respuesta a crisis 24/7 que apoya y ayuda a adolescentes, niños, padres y familias durante tiempos de crisis. Debe llamar primero."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-07-30T02:05:17.838972'),
    (306, N'The Shepherd’s Table at St. John’s', N'Food pantry', N'https://www.stjohnspringfield.com/the-shepards-table', N'', N'First and fourth Saturday, 10 a.m. to 1 p.m.', 1, N'{"Name": {"Value": {"en": "The Shepherd’s Table at St. John’s"}}, "Description": {"Value": {"en": "Food boxes provided.", "es": "Se ofrece cajas de comida."}}, "HoursOfOperation": {"Value": {"en": "First and fourth Saturday, 10 a.m. to 1 p.m.", "es": "Primero y cuarto sábado, 10 a.m. a 1 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-30T18:53:21.580667'),
    (307, N'Thurston Food Pantry inside Waypoint Community Church', N'Pre-packed food boxes third Saturday of each month. Some paperwork the first visit.', N'https://www.ccslc.org/food-and-emergency-help', N'', N'Third Saturday of every month 9 a.m. to 11 p.m.', 1, N'{"Name": {"Value": {"en": "Thurston Food Pantry inside Waypoint Community Church"}}, "Description": {"Value": {"en": "Pre-packed food boxes third Saturday of each month. Some paperwork the first visit.", "es": "Cajas de comida empaquetadas el tercer sábado de cada mes. Un poco de papeleo la primera visita."}}, "HoursOfOperation": {"Value": {"en": "Third Saturday of every month 9 a.m. to 11 p.m.", "es": "Tercer sábado de cada mes de 9 a.m. a 11 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (308, N'Trans Lifeline', N'A national hotline that provides peer counseling in response to crisis situations for transgender individuals. Run by trans for trans. Also can guide trans individuals to grants.', N'https://www.translifeline.org/', N'', N'All hours, all days', 1, N'{"Name": {"Value": {"en": "Trans Lifeline"}}, "Description": {"Value": {"en": "A national hotline that provides peer counseling in response to crisis situations for transgender individuals. Run by trans for trans. Also can guide trans individuals to grants.", "es": "Una línea directa nacional que ofrece asesoramiento entre pares en respuesta a situaciones de crisis para personas transgénero. Dirigido por trans para trans. También guían a las personas trans a las subvenciones."}}, "HoursOfOperation": {"Value": {"en": "All hours, all days", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (309, N'TransPonder', N'Provides community, resources, and support groups for transgendered folks, questioning and parents. Website provides a list of providers that are LGBTQIA+ affirmative. Please contact via website or call for full services, places and times. Leave a message on the phone and they will get back to you. ', N'https://transponder.community/', N'info@transponder.community', N'Call for available services. Leave message anytime. ', 1, N'{"Name": {"Value": {"en": "Trans*Ponder"}}, "Description": {"Value": {"en": "Provides community and resources for transgendered individuals. Provide a yoga class and support groups for transgendered folks, questioning and parents. Website provides a list of providers that are LGBTQ affirmative. Please contact via website or email for full services, places and times. Leave message on the phone and they will get back. Also check Facebook: facebook.com/transponderpublic \\n\\nCOVID Update: Social groups meet on Zoom.", "es": "Trans*Ponder ofrece comunidad y recursos para personas transgénero. Ofrecen una clase de yoga y grupos de apoyo para personas transgénero, interrogantes y padres. El sitio web ofrece una lista de proveedores que son afirmativos LGBTQ. Póngase en contacto por teléfono o correo electrónico para conocer todos los servicios, lugares y horarios. Deja un mensaje y te responderán."}}, "HoursOfOperation": {"Value": {"en": "Call for available services. Leave message anytime.", "es": "Llame para conocer los servicios disponibles. Deja un mensaje en cualquier momento."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-07-30T02:06:06.638412'),
    (310, N'Trevor Lifeline', N'A crisis intervention and suicide prevention phone service for LGBTQIA. Or, text “START” to 678678 (standard text-messaging rates apply).', N'https://www.thetrevorproject.org/', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Trevor Lifeline"}}, "Description": {"Value": {"en": "A crisis intervention and suicide prevention phone service for LGBTQIA. Or, text “START” to 678678 (standard text-messaging rates apply).", "es": "Un servicio telefónico de intervención en crisis y prevención del suicidio para LGBTQIA. O envíe un mensaje de texto con la palabra “COMENZAR” al 678678 (se aplican tarifas estándar de mensajes de texto)."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (311, N'Triangle Food Box', N'Food pantry open Friday following the third Thursday of each month, from 10 a.m. to 2 p.m. Clothing and other goods sometimes available.', N'https://www.facebook.com/trianglefoodbox/', N'', N'Friday following the third Thursday of the month 10am-2pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-31T16:55:54.218264'),
    (312, N'University of Oregon Knight Library', N'Public workstations provide full access to the library catalog, the libraries'' electronic databases and resources, information about the libraries, and open Internet access. Public workstations are available on a first come/first served basis and are limited to 30 minutes.', N'https://library.uoregon.edu/knight-library', N'', N'Monday to Friday, 7am to 9pm during the school year and 9am to 7pm during the summer.', 1, N'{"Name": {"Value": {"en": "University of Oregon Knight Library"}}, "Description": {"Value": {"en": "Public workstations provide full access to the library catalog, the libraries'' electronic databases and resources, information about the libraries, and open Internet access. Public workstations are available on a first come/first served basis and are limited to 30 minutes.\\n\\nCOVID Update: Open only to UO faculty, students, and staff with current UO ID cards.", "es": "Las estaciones de trabajo públicas ofrece acceso completo al catálogo de la biblioteca, las bases de datos y los recursos electrónicos de las bibliotecas, la información sobre las bibliotecas y el acceso abierto a Internet. Las estaciones de trabajo públicas están disponibles por orden de llegada y están limitadas a 30 minutos.\\n\\nActualización de COVID: Abierto solo para profesores, estudiantes y personal de UO con tarjetas de identificación de UO vigentes."}}, "HoursOfOperation": {"Value": {"en": "Monday to Thursday, 8 a.m. to 9 p.m.; Friday, 8 a.m. to 7 p.m.", "es": "Lunes a jueves de 8 a.m. a 9 p.m .; Viernes de 8 a.m. a 7 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-31T18:57:43.483945'),
    (313, N'Up River Food Pantry', N'Food boxes', N'https://foodfinder.oregonfoodbank.org/locations/up-river-pantry-culp-creek', N'', N'First and third Friday of every month, 4:00 to 5:00 p.m.', 1, N'{"Name": {"Value": {"en": "Up River Food Pantry"}}, "Description": {"Value": {"en": "Food boxes", "es": "Cajas de comida"}}, "HoursOfOperation": {"Value": {"en": "First and third Friday of every month, 4:00 to 5:00 p.m.", "es": "Primer y tercer viernes de cada mes, de 4:00 a 5:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (315, N'Veterans Crisis Hotline', N'Support line for all veterans, service members, National Guard members and their families. Translation service available.', N'', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Veterans Crisis Hotline"}}, "Description": {"Value": {"en": "Support line for all veterans, service members, National Guard members and their families. Translation service available.", "es": "Línea de apoyo para todos los veteranos, miembros del servicio, miembros de la Guardia Nacional y sus familias. Servicio de traducción disponible."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (316, N'Veterans Homeless Services Hotline', N'A national line that provides referral to services for homeless veterans or veterans at risk of becoming homeless. Others can also request referrals on behalf of veterans. Veterans will be referred to the Housing Coordinator at their local VA Medical Center for assistance. Translation service available.', N'www.va.gov/homeless/crrc.asp', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Veterans Homeless Services Hotline"}}, "Description": {"Value": {"en": "A national line that provides referral to services for homeless veterans or veterans at risk of becoming homeless. Others can also request referrals on behalf of veterans. Veterans will be referred to the Housing Coordinator at their local VA Medical Center for assistance.\\n\\nTranslation service available.", "es": "Una línea nacional que ofrece referencias a servicios para veteranos sin hogar o veteranos en riesgo de quedarse sin hogar. Otros también pueden solicitar referencias en nombre de los veteranos. Los veteranos serán referidos al Coordinador de Vivienda en su Centro Médico VA local para recibir asistencia.\\n\\nServicio de traducción disponible."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-31T19:08:52.196755'),
