    (324, N'Volunteers in Medicine Clinic of Lane County', N'Lane county''s only free healthcare clinic. Provide primary care and referrals. Focuses on providing care for medically underserved adults. Call for a prescreening interview.', N'https://vim-clinic.org/patients/services-eugene/', N'', N'Monday/Wednesday/Thursday 9am-noon and 1:30pm-5pm, Tuesday 1:30pm-5pm and 5:30pm-8pm', 1, NULL, N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-03-31T22:28:01.880107'),
    (325, N'Washington-Jefferson Park Syringe Drop-off', N'Syringe drop-off at container. When checking the HIV Alliance website, please excuse the street address they''ve included for the Washington-Jefferson Park, for all familiar with Eugene, that will look off, and it is off. The address included here, near the skatepark, is the one.', N'https://hivalliance.org/prevent/syringe-services/', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Washington-Jefferson Park Syringe Drop-off"}}, "Description": {"Value": {"en": "Syringe drop-off at container. When checking the HIV Alliance website, please excuse the street address they''ve included for the Washington-Jefferson Park, for all familiar with Eugene, that will look off, and it is off. The address included here, near the skatepark, is the one.", "es": "Caída de la jeringa en el recipiente. Al consultar el sitio web de HIVAlliance, disculpe la dirección postal que han incluido para el Washington-Jefferson Park, para todos los que estén familiarizados con Eugene, se verá mal y está apagado. La dirección incluida aquí, cerca del skatepark, es la indicada."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre abierto"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (326, N'Waste to Taste', N'A walk-in food pantry where you fill your own food boxes. By appointment only. Contact website to make an appointment. If you have questions please email info@burritobrigade.org.', N'https://burritobrigade.org/waste-to-taste/', N'info@burritobrigade.org', N'Mondays and Wednesdays 4 to 6 PM, Thursday and Friday 3 to 5PM.', 1, N'{"Name": {"Value": {"en": "Waste to Taste"}}, "Description": {"Value": {"en": "A walk-in food pantry where you fill your own food boxes. By appointment only. Contact website to make an appointment. Masks required. If you have questions please email info@burritobrigade.org.", "es": "Una despensa de alimentos sin cita previa donde puede llenar sus propias cajas de alimentos. Solo por cita. Póngase en contacto con el sitio web para concertar una cita. Se requieren máscaras. Si tiene preguntas, envíe un correo electrónico a info@burritobrigade.org."}}, "HoursOfOperation": {"Value": {"en": "Monday to Thursday, 4 to 6 p.m.", "es": "De lunes a jueves, de 4 a 6 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-05T02:53:15.987883'),
    (327, N'Black Thistle Wednesday Clinic', N'Black Thistle Street Aid provides a monthly FREE medical clinic and street outreach services. Prescription refills, wound care, referrals, hygiene supplies, ready-to-eat food, harm-reduction supplies. Other community organizations are present.', N'', N'blackthistle.streetaid@gmail.com', N'Every second Wednesday of the month, 12:30a.m. to 3:30 p.m.', 1, N'{"Name": {"Value": {"en": "Wednesday Clinic"}}, "Description": {"Value": {"en": "Black Thistle Street Aid provides a monthly FREE medical clinic and street outreach services. Prescription refills, wound care, referrals, hygiene supplies, ready-to-eat food, harm-reduction supplies. Other community organizations are present.", "es": "Black Thistle Street Aid proporciona una clínica médica GRATUITA y servicios de extensión en la calle. Resurtidos de recetas, cuidado de heridas, referencias, suministros de higiene, alimentos listos para comer, suministros para la reducción de daños. Otros organizaciones de la comunidad están allí también."}}, "HoursOfOperation": {"Value": {"en": "Every second Wednesday of the month, 12:30a.m. to 3:30 p.m.", "es": "Cada segundo miércoles del mes, 12:30 a.m. hasta las 3:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-05T02:58:02.079349'),
    (328, N'Western Lane Fire & EMS Authority ', N'Mobile Crisis Response Unit serving the community of Florence and Western Lane County. Support to people in crisis, including sudden death, loss of home due to fire, depression, suicidal ideation/threat, chronic mental illness, homelessness. Mainly dispatched through law enforcement/911.', N'https://www.wlfea.org/', N' info@wlfea.org', N'Business hours: 8am to 5pm Monday – Friday. (Closed on most Federal Holidays)', 1, N'{"Name": {"Value": {"en": "Western Lane Fire & EMS Authority"}}, "Description": {"Value": {"en": "Mobile Crisis Response Unit serving the community of Florence and Western Lane County. Support to people in crisis, including sudden death, loss of home due to fire, depression, suicidal ideation/threat, chronic mental illness, homelessness. Mainly dispatched through law enforcement/911.", "es": ""}}, "HoursOfOperation": {"Value": {"en": "", "es": ""}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-05T03:10:16.132483'),
    (329, N'White Bird - Chrysalis Behavioral Health Outpatient Services', N'Services for substance abuse and mental health care through individual and group counseling. Also, an opiate treatment program, DUII education and rehabilitation.  Intake form available online.', N'https://whitebirdclinic.org/', N'', N'Monday to Thursday, 9 a.m. to 6 p.m. (closed Thursday 11:30 a.m. to 2:30 p.m.)', 1, N'{"Name": {"Value": {"en": "White Bird - Chrysalis Behavioral Health Outpatient Services"}}, "Description": {"Value": {"en": "Services for substance abuse and mental health care through individual and group counseling. Also, an opiate treatment program, DUII education and rehabilitation. Intake form available online.", "es": "Servicios para el abuso de sustancias y la atención de la salud mental mediante asesoramiento individual y grupal. Además, un programa de tratamiento con opiáceos. También ofrece educación y rehabilitación de DUII."}}, "HoursOfOperation": {"Value": {"en": "Monday to Thursday, 9 a.m. to 6 p.m. (closed Thursday 11:30 a.m. to 2:30 p.m.)", "es": "Lunes a jueves de 9 a.m. a 6 p.m. (cerrado jueves 11:30 a.m. a 2:30 p.m.)"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (330, N'White Bird - Community Dental Clinic', N'Emergency, preventative, and restorative dental care to people who may be uninsured, underinsured, low income or homeless, and may otherwise go without care. Services include: filling, crowns, endodontics, extractions, periodonture, bridges, prophylaxis, application of fluoride and sealants and oral health education. Oregon Health Plan / Trillium and private dental insurance accepted. Uninsured patients are charged on a sliding scale based on income.', N'https://whitebirdclinic.org/', N'', N'Monday - Thursday 8 AM - 5PM, Friday 8AM- 3PM. Walkins: Monday and Wednesday starting at 7:30 AM', 1, N'{"Name": {"Value": {"en": "White Bird - Community Dental Clinic"}}, "Description": {"Value": {"en": "Emergency, preventative, and restorative dental care to people who may be uninsured, underinsured, low income or homeless, and may otherwise go without care. Services include: filling, crowns, endodontics, extractions, periodonture, bridges, prophylaxis, application of fluoride and sealants and oral health education. Oregon Health Plan / Trillium and private dental insurance accepted. Uninsured patients are charged on a sliding scale based on income.", "es": "Atención dental de emergencia, preventiva y restauradora para personas que pueden no tener seguro, tener seguro insuficiente, tener bajos ingresos o estar sin hogar y, de lo contrario, pueden quedar sin atención. Los servicios ofrecidos incluyen: empastes, coronas, endodoncia, extracciones, periodoncia, puentes, profilaxis, aplicación de flúor y selladores y educación en salud bucal. Se aceptan Oregon Health Plan / Trillium y seguro dental privado. A los pacientes sin seguro se les cobra según una escala móvil basada en los ingresos."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 5 p.m.", "es": "Lunes a viernes de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-05T03:23:49.141579'),
    (331, N'White Bird - Counseling Program', N'Provides individual and family counseling. This therapy is for adults wanting to clarify and explore issues in their lives and/or for more in-depth healing and growth. Also provides end-of-life counseling. No walk in; please make an appointment. Intake form available online.', N'https://whitebirdclinic.org/', N'', N'Reception hours Monday to Thurs 9AM-2PM, Friday by phone 9AM-2PM Therapy available Monday -Friday 9AM-5PM some earlier or later appointments available by request. ', 1, N'{"Name": {"Value": {"en": "White Bird - Counseling Program"}}, "Description": {"Value": {"en": "Provides individual and family counseling. This therapy is for adults wanting to clarify and explore issues in their lives and/or for more in-depth healing and growth. Also provides end-of-life counseling. No walk in; please make an appointment. Intake form available online.", "es": "Ofrece asesoramiento individual y familiar. Esta terapia es para adultos que desean aclarar y explorar problemas en sus vidas y / o para una curación y crecimiento más profundos. También ofrece asesoramiento sobre el final de la vida. Llame para una entrevista de admisión gratuita y una revisión de las opciones de asesoramiento. No se permite entrar, haga una cita."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 5 p.m.", "es": "Lunes a viernes de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-05T03:26:37.128894'),
    (332, N'White Bird - Front Rooms Resource Center', N'Provides water, a mail/messaging service, phone access, clothing, first aid kits, and hygiene supplies. Porta-potties are available outside of the building. Syringe drop-off site. Also provides vouchers for no-cost vision exams, lenses and frames.', N'https://whitebirdclinic.org/front-rooms', N'', N'Every day in person services, 9:00 a.m. to 12:15 PM, 1:30 PM to 4:30 PM Close at 3:30 on Wednesdays White Bird Information and referral reception services 8:30AM – 12:30 PM and 1:00 PM to 5 PM Close at 3:30 on Wednesdays', 1, N'{"Name": {"Value": {"en": "White Bird - Front Rooms Resource Center"}}, "Description": {"Value": {"en": "Provides water, a mail/messaging service, phone access, clothing, and hand washing. Porta-potties are available outside of the building. Syringe drop-off site. Also provides vouchers for no-cost vision exams, lenses and frames.", "es": "White Bird Front Rooms ofrece agua, servicio de correo / mensajería, acceso telefónico, ropa y lavado de manos. Porta-orinales están disponibles fuera del edificio. Lugar de entrega de jeringas. También ofrece vales para exámenes de la vista, lentes y marcos sin costo."}}, "HoursOfOperation": {"Value": {"en": "Every day, 9:30 a.m. to 4:30 p.m.", "es": "Todos los días de 9:30 a.m. a 4:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-05T16:43:51.392308'),
    (333, N'White Bird - Medical Clinic', N'Clinicians provide primary care, perform preventative exams, treat injuries, perform minor procedures, and connect patients with mental health and chemical dependency services. COVID-19 testing available. White Bird Medical Clinic accepts most Medicare B and Oregon Health Plan (OHP) insurance.', N'https://whitebirdclinic.org/', N'', N'Monday to Friday, 9 a.m. to 6 p.m. (closed Mondays 12:30 to 2:30 p.m.)', 1, N'{"Name": {"Value": {"en": "White Bird - Medical Clinic"}}, "Description": {"Value": {"en": "Clinicians provide primary care, perform preventative exams, treat injuries, perform minor procedures, and connect patients with mental health and chemical dependency services. COVID-19 testing available. White Bird Medical Clinic accepts most Medicare B and Oregon Health Plan (OHP) insurance.", "es": "Nuestros médicos ofrece atención primaria, realizan exámenes preventivos, tratan lesiones, realizan procedimientos menores y conectan a los pacientes con servicios de salud mental y dependencia química. Prueba COVID-19 disponible. White Bird Medical Clinic acepta la mayoría de los seguros de Medicare B y del Plan de Salud de Oregon (OHP)."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 9 a.m. to 6 p.m. (closed Mondays 12:30 to 2:30 p.m.)", "es": "Lunes a viernes de 9 a.m. a 6 p.m. (cerrado algunos lunes de 12:30 a 2:30 p.m.)"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (334, N'White Bird - Navigation Empowerment Services Team (NEST)', N'Assistance with SSI/SSDI assistance from a public benefits specialist. Oregon birth certificate requests, transportation to appointments. Phone access, direct express cards, Assurance/Lifeline phones, and food stamps. Helps clients sign up for the Oregon Health Plan and purchasing private insurance through www.healthcare.gov. Walk in during open hours. Assistance is available by phone until 2 p.m.', N'https://whitebirdclinic.org/nest', N'', N'Tuesday and Thursday from 9:30 a.m. to 12:30 p.m. and 2:00 p.m. to 4:00 p.m. Wednesday from 9:30 a.m. to 12:30 pm. Assistance is also available by phone at 541-342-1295 (9:30 a.m. to 3:00 p.m.).  Front Door Assessments Monday and Friday 9:30 am -2 pm', 1, N'{"Name": {"Value": {"en": "White Bird - Navigation Empowerment Services Team (NEST)"}}, "Description": {"Value": {"en": "Assistance with SSI/SSDI assistance from a public benefits specialist. Oregon birth certificate requests, transportation to appointments. Phone access, direct express cards, Assurance/Lifeline phones, and food stamps. Helps clients sign up for the Oregon Health Plan and purchasing private insurance through www.healthcare.gov. Walk in during open hours. Assistance is available by phone until 2 p.m.", "es": "Asistencia con la asistencia de SSI / SSDI de un especialista en beneficios públicos. Solicitudes de certificado de nacimiento de Oregon, transporte a las citas. Acceso telefónico, tarjetas directas express, teléfonos Assurance / Lifeline y cupones de alimentos. Ayuda a los clientes a inscribirse en el Plan de Salud de Oregon y a comprar un seguro privado a través de www.healthcare.gov. Camine durante las horas abiertas. La asistencia está disponible por teléfono hasta las 2 p.m."}}, "HoursOfOperation": {"Value": {"en": "Monday to Thursday 9:30 a.m. to 12 p.m.", "es": "Lunes a jueves de 9:30 a.m. a 12 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-05T19:07:04.322965'),
    (335, N'White Bird 24/7 Crisis Line', N'24/7 humanistic, person-centered crisis intervention by phone, free taxi rides for clients with significant mental health-related disabilities, and Lane County Information and Referral for social services. After-hours point of contact for 15th Night.', N'https://whitebirdclinic.org/crisis', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "White Bird 24/7 Crisis Line"}}, "Description": {"Value": {"en": "24/7 humanistic, person-centered crisis intervention by phone, free taxi rides for clients with significant mental health-related disabilities, and Lane County Information and Referral for social services. After-hours point of contact for 15th Night.", "es": "Intervención de crisis humanística y centrada en la persona las 24 horas del día, los 7 días de la semana, por teléfono, viajes en taxi gratuitos para clientes con discapacidades importantes relacionadas con la salud mental e información y remisión del condado de Lane para servicios sociales. Punto de contacto fuera del horario de atención para la 15th Night."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (336, N'White Bird Needle Exchange', N'The program works to keep sterile syringes accessible so that those who inject drugs or hormones do not feel a need to share their syringes and risk becoming infected with HIV, HCV, or another blood-borne disease.', N'https://hivalliance.org/prevent/syringe-services/', N'', N'Wednesdays 6:00 p.m. to 7:30 p.m.', 1, N'{"Name": {"Value": {"en": "White Bird Needle Exchange"}}, "Description": {"Value": {"en": "The program works to keep sterile syringes accessible so that those who inject drugs or hormones do not feel a need to share their syringes and risk becoming infected with HIV, HCV, or another blood-borne disease.", "es": "El programa trabaja para mantener accesibles las jeringas estériles para que quienes se inyectan drogas u hormonas no sientan la necesidad de compartir sus jeringas y corran el riesgo de infectarse con el VIH, el VHC u otra enfermedad transmitida por la sangre."}}, "HoursOfOperation": {"Value": {"en": "Wednesdays 6:00 p.m. to 7:30 p.m.", "es": "Miércoles a partir de las 6:00 p.m. a las 7:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (338, N'Willamette Family Inc. - Downtown Treatment Center', N'Same day treatment services for those in crisis with mental health issues and alcohol or drug abuse. After intake, there are immediate services, including transportation to sobering or detox. Transitional housing is available for clients only. Includes women''s and men''s residential services. Single women or mothers with children under 4 years old residential services available.Walk in or call.', N'https://wfts.org/rac.htm', N'', N'M-F 8-5 Call for info on outpatient courses. ', 1, N'{"Name": {"Value": {"en": "Willamette Family Inc. - Rapid Access Center"}}, "Description": {"Value": {"en": "Same day treatment services for those in crisis with mental health issues and alcohol or drug abuse. After intake, there are immediate services, including transportation to sobering or detox. Transitional housing is available for clients only. Walk in or call.", "es": "Servicios de tratamiento el mismo día para personas en crisis con problemas de salud mental y abuso de alcohol o drogas. Después de la ingesta, hay servicios inmediatos, incluido el transporte para dejar de beber o desintoxicarse. La vivienda de transición está disponible solo para clientes. Entra o llama."}}, "HoursOfOperation": {"Value": {"en": "Monday to Thursday 8 a.m. to 5 p.m., Friday 8 a.m. to 4:30 p.m.", "es": "Lunes a jueves de 8 a.m. a 5 p.m., viernes de 8 a.m. a 4:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-05T20:02:44.102238'),
    (339, N'Hope and Safety Alliance', N'Confidential, emergency shelter for families and individuals leaving a dangerous situation. Access to shelter is through the 24-hour crisis and support line or meeting with an advocate.   Web chat available on website.', N'https://www.hopesafetyalliance.org/', N'', N'Monday to Friday, 9 a.m. to 5 p.m.; 24-hour crisis hotline', 1, N'{"Name": {"Value": {"en": "Womenspace"}}, "Description": {"Value": {"en": "Confidential, emergency shelter for families and individuals leaving a dangerous situation. Access to shelter is through the 24-hour crisis and support line or meeting with an advocate. Web chat available on website.\\n\\nCOVID Update: Drop-in service is currently not available but mobile advocates are responding to needs.", "es": "Refugio confidencial de emergencia para familias e individuos que salen de una situación peligrosa. El acceso al refugio es a través de la línea de apoyo y crisis de 24 horas o la reunión con un defensor. Chat web disponible en el sitio web.\\n\\nActualización de COVID: el servicio sin cita previa no está disponible actualmente, pero los defensores móviles están respondiendo a las necesidades."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 9 a.m. to 5 p.m.; 24-hour crisis hotline", "es": "Lunes a viernes de 9 a.m. a 5 p.m.; Línea directa de crisis las 24 horas"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-05T20:51:02.392120');
INSERT INTO dbo.[Provider] ([ProviderId], [Name], [Description], [WebAddress], [EmailAddress], [HoursOfOperation], [IsActive], [l10N], [CreatedBy], [CreatedOn], [ModifiedBy], [ModifiedOn]) VALUES
    (340, N'Womenspace - Domestic Violence Advocacy Center', N'Emergency and support services for domestic violence survivors in intimate partner relationships. Includes emergency shelter, legal advocacy, transportation, safety planning, case management, and children and youth services. All services free of charge.', N'https://www.womenspaceinc.org/', N'', N'Monday to Friday, 9 a.m. to 4:30 p.m.', 1, N'{"Name": {"Value": {"en": "Womenspace - Domestic Violence Advocacy Center"}}, "Description": {"Value": {"en": "Emergency and support services for domestic violence survivors in intimate partner relationships. Includes emergency shelter, legal advocacy, transportation, safety planning, case management, and children and youth services. All services free of charge.\\n\\nCOVID Update: Drop-in service is currently not available, but mobile advocates are responding to needs.", "es": "Servicios de emergencia y apoyo para sobrevivientes de violencia doméstica en relaciones de pareja íntima. Esto incluye refugio de emergencia, defensa legal, transporte, planificación de seguridad, administración de casos y servicios para niños y jóvenes. Todos los servicios sin cargo"}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 9 a.m. to 4:30 p.m.", "es": "Lunes a viernes de 9 a.m. a 4:30 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-05T20:55:32.384127'),
    (341, N'Womenspace 24-hr. Hotline', N'24/7 crisis line for all victims and survivors of domestic violence, intimate partner violence, sexual assault and stalking in Lane County. Web chat available on website.', N'https://www.womenspaceinc.org/', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Womenspace 24-hr. Hotline"}}, "Description": {"Value": {"en": "24/7 crisis line for all victims and survivors of domestic violence, intimate partner violence, sexual assault and stalking in Lane County. Web chat available on website.", "es": "Línea de crisis las 24 horas, los 7 días de la semana para todas las víctimas y sobrevivientes de violencia doméstica, violencia de pareja íntima, agresión sexual y acecho en el condado de Lane. Chat web disponible en el sitio web."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (342, N'WorkSource Lane - Florence Office', N'The Job and Career Center provides job-search assistance, career counseling, job-finding workshops, resume and cover-letter writing assistance to all job seekers. Provides information about unemployment. Computer and internet access available for job search purposes.', N'http://worksourceoregon.org/', N'', N'Monday to Friday, 8 a.m. to noon, 1 p.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "WorkSource Lane - Florence Office"}}, "Description": {"Value": {"en": "The Job and Career Center provides job-search assistance, career counseling, job-finding workshops, resume and cover-letter writing assistance to all job seekers. Provides information about unemployment. Computer and internet access available for job search purposes.", "es": "El Job and Career Center ofrece asistencia para la búsqueda de empleo, asesoramiento profesional, talleres para encontrar empleo, asistencia para la redacción de currículums y cartas de presentación a todos los solicitantes de empleo. Ofrece información sobre el desempleo. Acceso a computadora e Internet disponible para fines de búsqueda de empleo."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to noon, 1 p.m. to 5 p.m.", "es": "Lunes a viernes, de 8 a.m. a mediodía, de 1 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (343, N'WorkSource Lane County', N'Provides job-search assistance, career counseling, job-finding workshops, resume and cover-letter writing assistance to all job seekers. Provides information about unemployment. Computer and internet access available for job search purposes.', N'http://worksourceoregon.org/', N'', N'Monday to Friday, 8 a.m. to 5 p.m.', 1, N'{"Name": {"Value": {"en": "WorkSource Lane County"}}, "Description": {"Value": {"en": "Provides job-search assistance, career counseling, job-finding workshops, resume and cover-letter writing assistance to all job seekers. Provides information about unemployment. Computer and internet access available for job search purposes.", "es": "El Job and Career Center ofrece asistencia para la búsqueda de empleo, asesoramiento profesional, talleres para encontrar empleo, asistencia para la redacción de currículums y cartas de presentación a todos los solicitantes de empleo. Ofrece información sobre el desempleo. Acceso a computadora e Internet disponible para fines de búsqueda de empleo."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8 a.m. to 5 p.m.", "es": "Lunes a viernes de 8 a.m. a 5 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'System Data Load', '2023-06-29T21:23:01.470000'),
    (344, N'Youth ERA - Eugene Drop in Center', N'Works to empower young people and create breakthroughs with the dedicated systems that serve them. Suicide Prevention and Crisis Response available.', N'https://www.youthera.org/eugene-drop', N'activatethe@youthera.org', N'Drop-in center M- F 3PM-6PM Call for peer support ', 1, N'{"Name": {"Value": {"en": "Youth ERA"}}, "Description": {"Value": {"en": "Works to empower young people and create breakthroughs with the dedicated systems that serve them. Suicide Prevention and Crisis Response available.", "es": "Trabaja para empoderar a los jóvenes y crear avances con los sistemas dedicados que les sirven."}}, "HoursOfOperation": {"Value": {"en": "Monday to Friday, 8:00 a.m. to 5 p.m.", "es": "Lunes a viernes de 3 a 6 p.m."}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-05T22:11:21.028123'),
    (345, N'Youthline', N'YouthLine is a free teen-to-teen crisis support and help line. YouthLine is confidential to a point- while we will never share conversations had on the lines, we are mandatory reporters. If a young person is unable to agree to safety for themselves or another person or if someone has experienced abuse or assault, YouthLine may contact other agencies to ensure the best support and safety for the young person in crisis. Teens are available from 4PM – 10PM otherwise adults staff the line. Text “teen2teen” to 839863.', N'https://oregonyouthline.org/', N'', N'All hours, every day', 1, N'{"Name": {"Value": {"en": "Youthline"}}, "Description": {"Value": {"en": "24/7 crisis line staffed by and for teenagers. Text “teen2teen” to 839863.", "es": "Línea de crisis 24/7 atendida por y para adolescentes. Envía "teen2teen" al 839863."}}, "HoursOfOperation": {"Value": {"en": "All hours, every day", "es": "Siempre disponible"}}}', N'System Data Load', '2023-06-29T21:23:01.470000', N'host', '2025-04-05T22:14:21.133944'),
    (346, N'Cafe 60 - Fern Ridge Senior Center', N'Individuals who are 60 years of age and over, and their spouses regardless of age, can enjoy a meal. Voluntary donations are welcome but not required. Reservations, however, are required. Please stop in or call to register.', N'https://midlanecares.com/senior-meals-programs-fern-ridge-service-center-veneta/', NULL, N'Monday, Wednesday, and Friday at 11 am', 0, NULL, N'host', '2025-04-06T22:56:54.192657', N'host', '2025-04-06T22:56:54.192657'),
