    (356, N'Plaza de Nuestra Comunidad - Springfield Education Office', N'Provides for the local Latino population: social services, alcohol and addiction treatment, community health care, translation services for youth and adults.', N'https://plazacomunidad.org/', NULL, N'Monday, Wednesday, Friday 8:30 am - 1:30 pm, Tuesday, Thursday 9 am - 12 pm', 0, NULL, N'host', '2025-04-12T00:02:12.727564', N'host', '2025-04-12T00:02:12.727564'),
    (357, N'Emergence Addiction and Behavior Therapies Counseling Program', N'Provides substance abuse, gambling, addiction, and mental health treatment. Support groups and outpatient care. Oregon Health Plan accepted. Call for appointment, no walk-ins. Zoom available.', N'http://4emergence.com', NULL, N'Monday to Friday 8am - 5pm', 0, NULL, N'host', '2025-04-19T18:59:05.710879', N'host', '2025-04-19T18:59:05.710879'),
